import torch
import torch.nn.functional as F
import contextlib
import inspect
import json
import math
import os
import shutil
import stat
import tempfile
import sys
import threading
import time
import warnings
import importlib
import importlib.util
from typing import Optional, Tuple
from torch.autograd import Function
from unsloth_zoo.mlx import is_mlx_available
from unsloth_zoo.rocm_build import is_rocm_torch
from unsloth_zoo.mxfp4_dequant import is_mxfp4_expert_param
from unsloth_zoo.packed_experts import is_new_packed_expert_param, is_packed_expert_param, packed_param_transposed

UNSLOTH_COMPILE_LOCATION = os.environ.get(
    "UNSLOTH_COMPILE_LOCATION", "unsloth_compiled_cache"
)

try:
    import bitsandbytes as bnb
    from bitsandbytes.nn import Params4bit
    # unsloth_zoo installs a permissive bitsandbytes stub wherever the real package is
    # absent, macOS arm64 among others, and every attribute of that stub resolves to a
    # placeholder object rather than a class. `isinstance(x, Params4bit)` against one
    # raises TypeError: isinstance() arg 2 must be a type, so a non-class Params4bit has
    # to count as no bitsandbytes at all. On a real install this is just True.
    HAS_BNB = isinstance(Params4bit, type)
    if not HAS_BNB:
        Params4bit = None
except Exception:
    # Not just ImportError: a bitsandbytes mismatched with torch fails its own import with AttributeError.
    HAS_BNB = False
    Params4bit = None

if not isinstance(Params4bit, type):
    # A bitsandbytes that imports but does not expose Params4bit as a class, which is what
    # the macOS build does, makes every `isinstance(param, Params4bit)` below raise
    # TypeError instead of answering False. Probe the object, not the platform or the
    # version, and treat that install as no bitsandbytes at all: there is no 4-bit expert
    # path without the class.
    HAS_BNB = False
    Params4bit = None


def _get_compile_location() -> str:
    return os.path.abspath(
        os.environ.get("UNSLOTH_COMPILE_LOCATION", UNSLOTH_COMPILE_LOCATION)
    )


def _log_info(message: str):
    if os.environ.get("UNSLOTH_ENABLE_LOGGING", "0") == "1":
        print(message)


def _warn_without_raising(message):
    """A warnings.warn that cannot fail the import: install_to_cache() runs at import, where simplefilter('error') would turn the warning into a raise."""
    try:
        warnings.warn(message)
    except Exception:
        print(message)


def _read_file_bytes(path):
    """The file's bytes, or None when it cannot be read."""
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError:
        return None


def _replace_with_copy(current_file, destination):
    """Use os.replace of a temp file, not shutil.copy: copy opens the destination, which read-only files refuse, and is not atomic across ranks at import."""
    directory = os.path.dirname(destination) or "."
    descriptor, temporary = tempfile.mkstemp(
        prefix = f".{os.path.basename(destination)}.", suffix = ".tmp", dir = directory,
    )
    try:
        # Write through the descriptor, not by reopening the name, since this directory is writable by whoever could
        # plant a copy and redirect the name; same as compiler._replace_compiled_cache_file.
        with os.fdopen(descriptor, "wb") as handle:
            descriptor = None
            with open(current_file, "rb") as source:
                shutil.copyfileobj(source, handle)
            handle.flush()
            # mkstemp is owner-only; keep the mode shutil.copy() would have left.
            mode = stat.S_IMODE(os.stat(current_file).st_mode)
            if hasattr(os, "fchmod"):
                os.fchmod(handle.fileno(), mode)
            else:
                os.chmod(temporary, mode)
        os.replace(temporary, destination)
    except BaseException:
        if descriptor is not None:
            try:
                os.close(descriptor)
            except OSError:
                pass
        try:
            os.remove(temporary)
        except OSError:
            pass
        raise


def install_to_cache(source_path, destination_filename=None):
    """Returns whether the cache copy is known to match source_path; an unwritable dir is not fatal, but a mismatched
    existing file is reported since _load_cached_moe_utils_module() execs it."""
    compile_location = _get_compile_location()
    if not os.path.exists(compile_location):
        try:
            os.makedirs(compile_location)
        except:
            pass

    current_file = os.path.abspath(source_path)
    if destination_filename is None:
        destination_filename = os.path.basename(current_file)

    destination = os.path.abspath(os.path.join(compile_location, destination_filename))

    if current_file == destination:
        return True

    current = _read_file_bytes(current_file)
    if current is not None and _read_file_bytes(destination) == current:
        # Already installed: this runs on every import of unsloth_zoo on every rank and copies this whole module, so
        # without the compare each import would overwrite it with an identical copy.
        return True

    try:
        _replace_with_copy(current_file, destination)
    except Exception as replace_error:
        # If a temp file cannot be made here, a plain copy is still tried to a destination we can write through; it
        # loses atomicity, so the readback below guards against partial copies.
        try:
            # Writing through a planted symlink would clobber whatever it targets.
            if os.path.islink(destination) or os.path.isdir(destination):
                raise OSError("destination is a symlink or directory")
            shutil.copy(current_file, destination)
        except Exception as copy_error:
            _log_info(
                f"Unsloth: Could not install {destination}: "
                f"{replace_error}; {copy_error}"
            )

    current = _read_file_bytes(current_file)
    installed = _read_file_bytes(destination)
    if installed is None or current is None:
        # Returns False when nothing landed or there is nothing to compare against, so no compiled module uses the cache copy.
        return False
    if installed == current:
        return True
    _warn_without_raising(
        f"Unsloth: {destination} does not match {current_file} and could not be "
        "replaced, so it will not be used. Delete it to restore the compiled "
        "cache copy."
    )
    return False


install_to_cache(__file__, "moe_utils.py")

_CACHED_FORWARD_MOE_BACKEND = None
_CACHED_MOE_UTILS_MODULE = None


_WARNED_STALE_CACHE = set()


def _cached_copy_is_current(cache_file, current_file) -> bool:
    """Whether the compiled cache holds this module byte for byte; a failed write could leave an older unsloth_zoo that
    callers would silently install, so this module is preferred and reported once."""
    cached = _read_file_bytes(cache_file)
    current = _read_file_bytes(current_file)
    if cached is None or current is None:
        return False
    if cached == current:
        return True

    if cache_file not in _WARNED_STALE_CACHE:
        _WARNED_STALE_CACHE.add(cache_file)
        logger = _moe_utils_logger()
        if logger is not None:
            logger.warning(
                f"Unsloth: {cache_file} is from a different version of unsloth_zoo and "
                f"could not be refreshed, so it is being ignored. Delete that directory "
                f"if MoE behaviour looks stale."
            )
    return False


def _remove_cached_bytecode(source_file):
    """Drop the .pyc beside a cache copy before executing it: the byte check covers only the .py, and CPython runs an
    unchecked-hash pyc unseen, so an undroppable pyc means falling back to our own defs."""
    try:
        bytecode_location = importlib.util.cache_from_source(source_file)
    except NotImplementedError:
        return True
    # A symlinked __pycache__ would send this unlink outside the cache, so refuse and use our own definitions; skipped
    # when sys.pycache_prefix is set, as that location is the user's own.
    if not getattr(sys, "pycache_prefix", None):
        try:
            if os.path.islink(os.path.dirname(bytecode_location)):
                return False
        except OSError:
            return False
    try:
        os.remove(bytecode_location)
    except FileNotFoundError:
        pass
    except OSError:
        return not os.path.isfile(bytecode_location)
    return True


def cached_copy_is_importable(directory) -> bool:
    """Never trusts a path that exists but is not a real directory (zipimport); no copy at all is True, but the caller
    must first run compiler._reject_shadowing_import_candidates; matching bytes are necessary, not sufficient;
    undroppable pyc means False."""
    try:
        # Only an existing non-directory is rejected; a missing path imports nothing and stays trusted, as a cache folder does before it is created.
        if os.path.exists(directory) and not os.path.isdir(directory):
            return False
        cache_file = os.path.abspath(os.path.join(directory, "moe_utils.py"))
    except Exception:
        return False
    current_file = os.path.abspath(__file__)
    if cache_file == current_file or not os.path.isfile(cache_file):
        return True
    if not _cached_copy_is_current(cache_file, current_file):
        return False
    return _remove_cached_bytecode(cache_file)


def _load_cached_moe_utils_module():
    global _CACHED_MOE_UTILS_MODULE

    cache_file = os.path.abspath(os.path.join(_get_compile_location(), "moe_utils.py"))
    current_file = os.path.abspath(__file__)
    if not os.path.isfile(cache_file) or cache_file == current_file:
        return None
    if not _cached_copy_is_current(cache_file, current_file):
        _CACHED_MOE_UTILS_MODULE = None
        return None

    # Differing cache bytes were not put there by install_to_cache(), yet exec_module would run them; return None and use this module's own definitions instead.
    cached_bytes = _read_file_bytes(cache_file)
    if cached_bytes is None or cached_bytes != _read_file_bytes(current_file):
        return None

    try:
        module_name = "unsloth_cached_moe_utils"
        module = sys.modules.get(module_name, None)
        if module is not None and os.path.abspath(getattr(module, "__file__", "")) == cache_file:
            _CACHED_MOE_UTILS_MODULE = module
            return module

        if not _remove_cached_bytecode(cache_file):
            return None

        spec = importlib.util.spec_from_file_location(module_name, cache_file)
        if spec is None:
            return None
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        try:
            # The bytes compared above, not a fresh read of the path. exec_module
            # reopens the file, and the comparison and that open are two moments:
            # a writer with access to the shared cache replaces the file between
            # them and its bytes run as unsloth_cached_moe_utils having matched
            # nothing. compiler.py's loader closed the same window; this one is
            # the copy of it that lives here.
            exec(compile(cached_bytes, cache_file, "exec"), module.__dict__)
        except Exception:
            sys.modules.pop(module_name, None)
            raise
        _CACHED_MOE_UTILS_MODULE = module
        return module
    except Exception:
        return None


def _select_moe_backend_eagerly(module):
    # Selecting inside a trace sets a guarded global and recompiles the graph once. While unsloth imports, a worker
    # that picks its card afterwards would probe (and open a context on) GPU 0: warm_moe_backend_selection selects at
    # model load instead.
    if torch.compiler.is_compiling() or _unsloth_importing():
        return
    try:
        module.select_moe_backend()
    except Exception:
        pass


def warm_moe_backend_selection():
    """Probe and select the MoE backend at model load (a temporary patch), before any trace; never during import."""
    module = _load_cached_moe_utils_module()
    for target in (module, sys.modules[__name__]):
        if target is not None and hasattr(target, "select_moe_backend"):
            _select_moe_backend_eagerly(target)


def get_forward_moe_backend():
    """Resolve forward_moe_backend from the compiled cache copy, else the local def."""
    global _CACHED_FORWARD_MOE_BACKEND
    module = _load_cached_moe_utils_module()
    if module is not None and hasattr(module, "forward_moe_backend"):
        _select_moe_backend_eagerly(module)
        _CACHED_FORWARD_MOE_BACKEND = module.forward_moe_backend
        return _CACHED_FORWARD_MOE_BACKEND

    _select_moe_backend_eagerly(sys.modules[__name__])
    _CACHED_FORWARD_MOE_BACKEND = forward_moe_backend
    return _CACHED_FORWARD_MOE_BACKEND

# Grouped MM wrapper around torch._grouped_mm; native backward works correctly.

# Dynamo calls a function decorated with this eagerly at trace time and bakes in its result.
_assume_constant_result = getattr(torch.compiler, "assume_constant_result", None) or \
    getattr(torch._dynamo, "assume_constant_result", lambda fn: fn)


def _match_grouped_mm_dtypes(inputs, weight):
    """torch._grouped_mm needs equal dtypes and is not on the autocast cast list: cast to the autocast dtype like
    F.linear (autograd tracked, so fp32 masters keep their grad), else promote to the wider dtype."""
    if inputs.dtype == weight.dtype or not (inputs.is_floating_point() and weight.is_floating_point()):
        return inputs, weight
    device_type = inputs.device.type
    try:
        autocast_dtype = (
            torch.get_autocast_dtype(device_type) if torch.is_autocast_enabled(device_type) else None
        )
    except (AttributeError, RuntimeError, TypeError):
        autocast_dtype = None
    if autocast_dtype in (torch.float16, torch.bfloat16):
        return inputs.to(autocast_dtype), weight.to(autocast_dtype)
    dtype = torch.promote_types(inputs.dtype, weight.dtype)
    return inputs.to(dtype), weight.to(dtype)


def _grouped_mm_with_backward_fix(
    inputs: torch.Tensor, weight: torch.Tensor, offsets: torch.Tensor
) -> torch.Tensor:
    """Passes the weight as a non-contiguous view when a one-time per-device probe matches the contiguous copy
    (bit-exact), else keeps the copy; falls back to per-group matmul on a 16-byte stride error or no
    torch._grouped_mm."""
    if _triton_grouped_mm_wanted(inputs, weight):
        return _triton_grouped_mm(inputs, weight, offsets)
    if inputs.dtype != weight.dtype:
        # Cast first so fp16 x fp32 masters reaches the compile-safe fp16 op below.
        inputs, weight = _match_grouped_mm_dtypes(inputs, weight)
    if (
        inputs.dtype == torch.float16
        and weight.dtype == torch.float16
        and _GROUPED_MM_FP16_OP is not None
        and torch.compiler.is_compiling()
    ):
        return _GROUPED_MM_FP16_OP(inputs, weight, offsets)
    return _grouped_mm_eager(inputs, weight, offsets)


def _grouped_mm_eager(inputs, weight, offsets):
    if inputs.dtype != weight.dtype:
        inputs, weight = _match_grouped_mm_dtypes(inputs, weight)
    inputs = inputs.contiguous()
    # Triton is picked when the probe says no, yet the separated LoRA delta still routed here: torch 2.8 hard-raises
    # unless dprops->major == 9, 2.6/2.7 lack _grouped_mm, so LoRA MoE died off H100; 2.9 falls back internally; probe
    # is cached.
    if not _grouped_mm_supported_on(inputs.device):
        return _manual_grouped_mm(inputs, weight, offsets)
    try:
        return _grouped_mm_native(inputs, weight, offsets)
    except RuntimeError as exc:
        refusal = _grouped_mm_refusal(exc)
        if refusal is None:
            raise
    # Outside the except: the traceback no longer pins this call's frames while the fallback runs.
    _latch_grouped_mm_refused(inputs.device, f"{str(inputs.dtype).replace('torch.', '')} call: {refusal}")
    if _triton_grouped_mm_wanted(inputs, weight):
        return _triton_grouped_mm(inputs, weight, offsets)
    return _manual_grouped_mm(inputs, weight, offsets)


_GROUPED_MM_REFUSALS = ("not supported on your system", "is only supported on cuda devices", "not supported on rocm")


def _grouped_mm_refusal(exc):
    """The message when exc is torch refusing grouped_mm for good, else None: an OOM or a shape error is not a latch."""
    if isinstance(exc, torch.OutOfMemoryError) or torch.compiler.is_compiling():
        return None
    message = str(exc).strip()
    lowered = message.lower()
    if not any(refusal in lowered for refusal in _GROUPED_MM_REFUSALS):
        return None
    return (message.splitlines() or [""])[0][:240]


def _latch_grouped_mm_refused(device, reason):
    """A real call refused what the probe passed: latch grouped_mm off for this GPU model."""
    global _TORCH_GROUPED_MM_SUPPORTED, _TRANSPOSED_VIEW_GROUPED_MM_SAFE
    kind = _grouped_mm_foreign_kind(device)
    if kind is None:
        _TORCH_GROUPED_MM_SUPPORTED = False
        _TRANSPOSED_VIEW_GROUPED_MM_SAFE = False
    else:
        _TORCH_GROUPED_MM_SUPPORTED_BY_KIND[kind] = False
        _TRANSPOSED_VIEW_SAFE_BY_KIND[kind] = False
    _GROUPED_MM_RUNTIME_REFUSALS[0] += 1
    # grouped_mm stays selected: later forwards run on Triton or the per-expert loop instead of raising.
    _GROUPED_MM_RUNTIME_LATCHED[0] = True
    _use_grouped_mm_triton_standin(device, reason)


_GROUPED_MM_RUNTIME_REFUSALS = [0]
_GROUPED_MM_RUNTIME_LATCHED = [False]


# Grouped GEMMs that read the expert offsets on the host (one sync per call). "torch_fallback": eager torch._grouped_mm
# forwards that torch serves with _grouped_mm_fallback, a per-expert mm loop (GroupedBlas.cpp: off bf16 sm90 / sm100,
# off cuBLASLt grouped on CUDA >= 13.3 sm9x-11x, and on ROCm without the opt-in CK kernels); torch's own backward adds
# up to two more per forward. "loop": Unsloth's per-expert loop (forward, backward and the dW loop; it runs eagerly
# even inside compiled code; also transformers' own fallback loop). "compiled_sites": such calls traced into a compiled
# graph, counted once per trace, since a graph cannot count its own runs. Read deltas around a step: grouped_mm_sync_calls().
GROUPED_MM_SYNC_CALLS = {"torch_fallback": 0, "loop": 0, "compiled_sites": 0}
_GROUPED_MM_SYNC_LOGGED = [False]
_TORCH_GROUPED_MM_FALLBACK_BY_KEY = {}


def grouped_mm_sync_calls():
    """Copy of GROUPED_MM_SYNC_CALLS (eager grouped GEMM calls that synced on the expert offsets)."""
    return dict(GROUPED_MM_SYNC_CALLS)


def _torch_grouped_mm_takes_fallback(device, dtype, weight_dtype, groups):
    """Whether torch._grouped_mm serves this call with its synced per-expert loop, from GroupedBlas.cpp's dispatch."""
    key = (device.type, device.index, dtype, weight_dtype, groups <= 1024)
    takes = _TORCH_GROUPED_MM_FALLBACK_BY_KEY.get(key)
    if takes is not None:
        return takes
    takes = True
    try:
        if device.type == "cuda":
            index = device.index if device.index is not None else torch.cuda.current_device()
            if is_rocm_torch(torch):
                arch = str(getattr(torch.cuda.get_device_properties(index), "gcnArchName", "")).split(":")[0]
                ck = os.environ.get("ROCM_ALLOW_GROUP_GEMM_CK", "0") == "1"
                takes = not (ck and arch in ("gfx942", "gfx950", "gfx90a"))
            else:
                major, minor = torch.cuda.get_device_capability(index)
                bf16 = dtype == weight_dtype == torch.bfloat16
                cuda = tuple(int(x) for x in (torch.version.cuda or "0.0").split(".")[:2])
                # bf16 takes cuBLASLt only behind an opt-in flag, so only fp16 is counted as served there.
                cublaslt = cuda >= (13, 3) and 9 <= major <= 11 and dtype == weight_dtype == torch.float16 \
                    and key[-1]
                takes = not (cublaslt or (bf16 and ((major, minor) == (9, 0) or major == 10)))
    except Exception:
        takes = True
    _TORCH_GROUPED_MM_FALLBACK_BY_KEY[key] = takes
    return takes


@_assume_constant_result
def _note_compiled_grouped_mm_site(device_type, device_index, dtype, weight_dtype):
    # Dynamo runs this once per trace (assume_constant_result), never inside the compiled graph.
    device = torch.device(device_type, device_index) if device_index is not None else torch.device(device_type)
    if _torch_grouped_mm_takes_fallback(device, dtype, weight_dtype, 1):
        _record_grouped_mm_sync("compiled_sites")
    return True


@_assume_constant_result
def _note_compiled_loop_site():
    # A traced call into an opaque per-expert loop op (transformers' grouped_mm_fallback), once per trace.
    _record_grouped_mm_sync("compiled_sites")
    return True


def _count_grouped_mm_sync(kind, inputs = None, weight = None, groups = 0):
    if torch.compiler.is_compiling():
        if kind == "opaque_loop":
            _note_compiled_loop_site()
        elif kind == "torch_fallback":
            # The expert count can be symbolic (dynamic=True), which the constant helper cannot take, so traced
            # calls are classified at 1 group: cuBLASLt's 1024-group limit is far above real expert counts.
            _note_compiled_grouped_mm_site(inputs.device.type, inputs.device.index, inputs.dtype, weight.dtype)
        return
    if kind == "torch_fallback" and not _torch_grouped_mm_takes_fallback(inputs.device, inputs.dtype, weight.dtype, groups):
        return
    # "opaque_loop": a caller's per-expert loop op (transformers' grouped_mm_fallback), a loop when run eagerly.
    _record_grouped_mm_sync("loop" if kind == "opaque_loop" else kind)


def _record_grouped_mm_sync(kind):
    # Shared with the compiled-cache copy of this module, so the package's counters see every call.
    package = sys.modules.get("unsloth_zoo.temporary_patches.moe_utils")
    calls = getattr(package, "GROUPED_MM_SYNC_CALLS", GROUPED_MM_SYNC_CALLS)
    logged = getattr(package, "_GROUPED_MM_SYNC_LOGGED", _GROUPED_MM_SYNC_LOGGED)
    calls[kind] += 1
    if not logged[0] and os.environ.get("UNSLOTH_ENABLE_LOGGING", "0") == "1":
        logged[0] = True
        where = "Unsloth's per-expert loop" if kind == "loop" else "torch._grouped_mm's per-expert fallback"
        print(
            f"Unsloth: MoE expert GEMMs run on {where}, one host sync per call. "
            "Per-step counts: unsloth_zoo.temporary_patches.moe_utils.grouped_mm_sync_calls()."
        )


def _grouped_mm_native(inputs, weight, offsets):
    _count_grouped_mm_sync("torch_fallback", inputs, weight, offsets.shape[0])
    pad = _native_backward_pad(inputs, weight)
    if pad:
        if _is_transposed_stack(weight) and _transposed_view_safe_on(inputs.device):
            # Pad the stored [E, N, K] rows and keep the view: padding the view itself copies the whole stack transposed,
            # which made it slower than the per-expert loop on T4.
            padded = F.pad(weight.transpose(-2, -1), (0, 0, 0, pad)).transpose(-2, -1)
        else:
            padded = F.pad(weight, (0, pad))
        try:
            return torch._grouped_mm(inputs, padded, offs=offsets)[:, :weight.shape[-1]]
        except RuntimeError as exc:
            if "strides should be multiple of 16 bytes" not in str(exc):
                raise
            return _manual_grouped_mm(inputs, weight, offsets)
    if not _transposed_view_safe_on(inputs.device):
        weight = weight.contiguous()   # view path unproven on this device -> safe copy
    try:
        return torch._grouped_mm(inputs, weight, offs=offsets)
    except RuntimeError as exc:
        if "strides should be multiple of 16 bytes" not in str(exc):
            raise
    weight = weight.contiguous()
    try:
        return torch._grouped_mm(inputs, weight, offs=offsets)
    except RuntimeError as exc:
        if "strides should be multiple of 16 bytes" not in str(exc):
            raise
        return _manual_grouped_mm(inputs, weight, offsets)


def _native_backward_pad(inputs, weight):
    """Zero columns that make N a 16-byte row when autograd records, else 0. torch._grouped_mm's own backward feeds
    grad [M, N] back into it: an unaligned N passes forward (transposed [E, N, K] stack) but raises in backward, so a
    trainable fp16 / bf16 stack with odd N died there. The padded columns are sliced off, so their grads are zero."""
    if not (torch.is_grad_enabled() and (inputs.requires_grad or weight.requires_grad)):
        return 0
    return -weight.shape[-1] % (16 // weight.element_size())


def _grouped_mm_fp16_wgrad_eager(inputs, grad_output, offsets):
    """dW[g] = inputs[g]^T @ grad_output[g] per group, as [G, K, N]; empty groups are zero."""
    # torch._grouped_mm rejects stride-0 (grad of y.sum()) or unaligned operands, which forced a per-expert loop: a host
    # sync and a different reduction than the compiled path; contiguous() avoids it.
    inputs = inputs.contiguous()
    grad_output = grad_output.contiguous()
    try:
        if _grouped_mm_supported_on(inputs.device):
            _count_grouped_mm_sync("torch_fallback", inputs, grad_output, offsets.shape[0])
            return torch._grouped_mm(inputs.transpose(-2, -1), grad_output, offs = offsets).contiguous()
    except RuntimeError:
        pass
    _count_grouped_mm_sync("loop")
    out = inputs.new_zeros((offsets.shape[0], inputs.shape[1], grad_output.shape[1]))
    start = 0
    for g, end in enumerate(offsets.tolist()):
        if end > start:
            out[g] = inputs[start:end].transpose(0, 1) @ grad_output[start:end]
        start = end
    return out


def _is_transposed_stack(weight):
    # [E, K, N] view of a contiguous [E, N, K] parameter (HF stores gate_up_proj / down_proj as [E, out, in]).
    return weight.dim() == 3 and not weight.is_contiguous() and weight.transpose(-2, -1).is_contiguous()


def _wgrad_in_weight_layout(wgrad, inputs, grad, offsets, transposed):
    # dW^T built contiguous and returned as its view: the leaf's layout, so AccumulateGrad does not copy it.
    if transposed:
        return wgrad(grad, inputs, offsets).transpose(-2, -1)
    return wgrad(inputs, grad, offsets)


def _register_grouped_mm_fp16_op():
    """Opaque fp16 torch._grouped_mm op so compiled fp16 MoE frames trace; eager takes fp16 on torch 2.10-2.14, but the
    meta/fake impl rejects it (2.14 accepts only with cuBLASLt, CUDA 13.3+); eager and bf16 never reach it;
    registered once per process."""
    if not hasattr(torch, "library") or not hasattr(torch.library, "custom_op"):
        return None
    try:
        return torch.ops.unsloth_zoo.grouped_mm_fp16.default
    except (AttributeError, RuntimeError):
        pass
    try:
        @torch.library.custom_op("unsloth_zoo::grouped_mm_fp16", mutates_args = ())
        def grouped_mm_fp16(inputs: torch.Tensor, weight: torch.Tensor, offsets: torch.Tensor) -> torch.Tensor:
            # contiguous: the real kernel pads the row stride to 16 bytes, the fake below does not.
            return _grouped_mm_eager(inputs, weight, offsets).contiguous()

        @grouped_mm_fp16.register_fake
        def _(inputs, weight, offsets):
            return inputs.new_empty((inputs.shape[0], weight.shape[-1]))

        @torch.library.custom_op("unsloth_zoo::grouped_mm_fp16_wgrad", mutates_args = ())
        def grouped_mm_fp16_wgrad(inputs: torch.Tensor, grad_output: torch.Tensor, offsets: torch.Tensor) -> torch.Tensor:
            return _grouped_mm_fp16_wgrad_eager(inputs, grad_output, offsets)

        @grouped_mm_fp16_wgrad.register_fake
        def _(inputs, grad_output, offsets):
            return inputs.new_empty((offsets.shape[0], inputs.shape[1], grad_output.shape[1]))

        def _setup_context(ctx, inputs, output):
            x, w, offs = inputs
            ctx.save_for_backward(x, w, offs)
            ctx.w_transposed = _is_transposed_stack(w)

        def _backward(ctx, grad):
            x, w, offs = ctx.saved_tensors
            grad = grad.contiguous()
            gx = gw = None
            if ctx.needs_input_grad[0]:
                gx = torch.ops.unsloth_zoo.grouped_mm_fp16(grad, w.transpose(-2, -1), offs)
            if ctx.needs_input_grad[1]:
                gw = _wgrad_in_weight_layout(
                    torch.ops.unsloth_zoo.grouped_mm_fp16_wgrad, x.contiguous(), grad, offs, ctx.w_transposed,
                )
            return gx, gw, None

        grouped_mm_fp16.register_autograd(_backward, setup_context = _setup_context)
        return torch.ops.unsloth_zoo.grouped_mm_fp16.default
    except Exception:
        return None


_GROUPED_MM_FP16_OP = _register_grouped_mm_fp16_op()


# Max avg rows per expert for Triton grouped-MM, per arch; off sm90/sm100 torch._grouped_mm is a per-expert cuBLAS loop
# that Triton beats for small experts; sm121 follows sm120 (unsloth-zoo issue 1661) except for dw. sm89 (L4, E 64-256,
# rows 8-1024 per expert) wins on every base GEMM with its retuned tiles. sm86 is unmeasured: it shares sm89's tile
# table (moe_grouped_fp16._generic_family) but keeps sm89's former 32-row limits until it is timed. sm75 has no Triton MMA, so only small LoRA
# GEMMs go there (one launch instead of one per expert); a LoRA limit counts rows at rank 16, a wider rank r as r / 16.
_TRITON_GROUPED_MM_AUTO_ROWS = {
    (8, 0):  {"lora": -1, "many": 2048, "few": 512, "dw": 128, "dw_few": 128},
    (12, 0): {"lora": -1, "many": 2048, "few": 256, "dw": 256, "dw_few": 64},
    (12, 1): {"lora": -1, "many": 2048, "few": 256, "dw": 64,  "dw_few": 64},
    (8, 9):  {"lora": -1, "many": 1024, "few": 32,  "dw": 0,   "dw_few": 0},
    (8, 6):  {"lora": -1, "many": 32,   "few": 32,  "dw": 0,   "dw_few": 0},
    (7, 5):  {"lora": 64, "many": 0,    "few": 0,   "dw": 0,   "dw_few": 0},
}
# ROCm, keyed by the gcnArch capability torch reports. There torch._grouped_mm is a per-expert mm loop, and on gfx1151
# ROCm 7.13 / 7.14 it fails the training-shaped probe, so the LoRA GEMMs ran as about 3.8k per-expert mm per step.
# gfx1151 (Strix Halo) LoRA GEMMs on Triton, Qwen3-30B-A3B layer shape (E 128, top-8), r16, bf16: 1.26x step speed on
# Linux. Windows (triton-windows) timed 1.76x on one box and 0.94x on another, so auto keeps it on the loop there.
# Base-sized classes are not timed yet and stay on torch; other ROCm archs keep the loop. =1 forces Triton anywhere.
_TRITON_GROUPED_MM_AUTO_ROWS_ROCM = {
    (11, 5): {"lora": -1, "many": 0, "few": 0, "dw": 0, "dw_few": 0},
}
_TRITON_GROUPED_MM_CAPABILITY = {}
_TRITON_GROUPED_MM_POLICY = {}
_GROUPED_MM_TRITON_STANDIN = False


def _triton_grouped_mm_capability(index):
    cap = _TRITON_GROUPED_MM_CAPABILITY.get(index)
    if cap is None:
        cap = _TRITON_GROUPED_MM_CAPABILITY[index] = tuple(torch.cuda.get_device_capability(index))
    return cap


@_assume_constant_result
def _triton_grouped_mm_max_rows(index, kind = "lora"):
    """Row limit for class kind on device index (0 off, -1 no limit), read from UNSLOTH_MOE_GROUPED_TRITON (auto|1|0),
    UNSLOTH_DISABLE_MOE_TRITON=1, UNSLOTH_MOE_GROUPED_TRITON_MAX_ROWS and the grouped_mm stand-in; baked in under
    torch.compile, so an env change needs torch._dynamo.reset()."""
    environ = os.environ
    key = (
        index, kind, environ.get("UNSLOTH_MOE_GROUPED_TRITON"), environ.get("UNSLOTH_DISABLE_MOE_TRITON"),
        environ.get("UNSLOTH_MOE_GROUPED_TRITON_MAX_ROWS"), _GROUPED_MM_TRITON_STANDIN,
    )
    limit = _TRITON_GROUPED_MM_POLICY.get(key)
    if limit is None:
        limit = _TRITON_GROUPED_MM_POLICY[key] = _triton_grouped_mm_policy(index, kind, *key[2:])
    return limit


@_assume_constant_result
def _triton_grouped_mm_lora_rank_scaled():
    """Auto LoRA limits count rows at rank 16; an explicit UNSLOTH_MOE_GROUPED_TRITON_MAX_ROWS is taken as given."""
    return not os.environ.get("UNSLOTH_MOE_GROUPED_TRITON_MAX_ROWS")


def _triton_grouped_mm_policy(index, kind, mode, disabled, override, standin = False):
    mode = (mode or "auto").strip().lower()
    if standin and mode == "auto":
        mode = "1"
    if mode in ("0", "false", "off") or disabled == "1":
        return 0
    if _GROUPED_MM_TRITON_OP is None or index is None:
        return 0
    rocm = is_rocm_torch(torch)
    try:
        from unsloth_zoo.temporary_patches.moe_grouped_fp16 import triton as _triton
        if _triton is None:
            return 0
        cap = _triton_grouped_mm_capability(index)
    except Exception:
        return 0
    if mode in ("1", "true", "on"):
        # Below sm80 Triton has no MMA: forcing it on still keeps base-sized GEMMs on cuBLAS.
        limit = -1 if rocm or cap >= (8, 0) or (cap >= (7, 5) and kind == "lora") else 0
    else:
        if rocm:
            table = {} if sys.platform == "win32" else _TRITON_GROUPED_MM_AUTO_ROWS_ROCM
        else:
            table = _TRITON_GROUPED_MM_AUTO_ROWS
        limit = table.get(cap, {}).get(kind, 0)
    if limit != 0 and override:
        try:
            limit = int(override)
        except ValueError:
            pass
    return limit


def _triton_grouped_mm_kind(K, N, E):
    return "lora" if min(K, N) <= 32 else ("many" if E >= 64 else "few")


def _rows_within(limit, M, E):
    return limit != 0 and (limit < 0 or M <= limit * E)


_PLAIN_TENSOR_TYPES = (torch.Tensor, torch.nn.Parameter)


def _triton_grouped_mm_wanted(inputs, weight) -> bool:
    """Static gate (never reads offsets' values): use Triton when M <= limit * E for the GEMM's class."""
    device = inputs.device
    if device.type != "cuda":
        return False
    if _triton_grouped_mm_max_rows(device.index, "lora") == 0 or inputs.dim() != 2 or weight.dim() != 3 \
            or weight.device != device:
        return False
    dtype = inputs.dtype
    if weight.dtype != dtype or (dtype != torch.bfloat16 and dtype != torch.float16):
        return False
    # Tensor subclasses (DTensor, float8 / quantized wrappers) keep torch._grouped_mm's own dispatch.
    if type(inputs) not in _PLAIN_TENSOR_TYPES or type(weight) not in _PLAIN_TENSOR_TYPES:
        return False
    E, K, N = weight.shape
    if E == 0 or inputs.shape[1] != K or N == 0:
        return False
    return _triton_grouped_mm_rows_ok(device, inputs.shape[0], E, K, N)


def _triton_grouped_mm_rows_ok(device, M, E, K, N):
    kind = _triton_grouped_mm_kind(K, N, E)
    limit = _triton_grouped_mm_max_rows(device.index, kind)
    if kind == "lora" and limit > 0 and _triton_grouped_mm_lora_rank_scaled():
        # Triton's LoRA cost grows with the rank, the per-expert loop's does not; ceil so no row is over budget.
        M = (M * max(min(K, N), 16) + 15) // 16
    return _rows_within(limit, M, E)


def _grouped_mm_triton_impl(inputs, weight, offsets):
    from unsloth_zoo.temporary_patches import moe_grouped_fp16 as mg
    if not mg.triton_grouped_available(inputs.device):
        mg.GENERIC_CALLS["fallback"] += 1
        return _grouped_mm_eager(inputs, weight, offsets).contiguous()
    return mg.generic_grouped_mm(inputs, weight, offsets)


def _grouped_mm_triton_wgrad_impl(inputs, grad, offsets):
    from unsloth_zoo.temporary_patches import moe_grouped_fp16 as mg
    if not mg.triton_grouped_available(inputs.device):
        mg.GENERIC_CALLS["fallback"] += 1
        return _grouped_mm_fp16_wgrad_eager(inputs, grad, offsets).contiguous()
    E, K, N = offsets.shape[0], inputs.shape[1], grad.shape[1]
    dw_kind = "dw" if E >= 64 else "dw_few"
    if min(K, N) > 32 and not _rows_within(_triton_grouped_mm_max_rows(inputs.device.index, dw_kind), inputs.shape[0], E):
        # A trainable base stack's dW (full finetuning): cuBLAS beats the Triton reduction at these sizes.
        return _grouped_mm_fp16_wgrad_eager(inputs, grad, offsets).contiguous()
    return mg.generic_grouped_wgrad(inputs, grad, offsets, E)


class _GroupedMMTriton(torch.autograd.Function):
    """Eager twin of unsloth_zoo::grouped_mm_triton, skipping the custom op's ~30 us dispatch cost."""

    @staticmethod
    def forward(ctx, inputs, weight, offsets):
        ctx.save_for_backward(
            inputs if ctx.needs_input_grad[1] else None, weight if ctx.needs_input_grad[0] else None, offsets,
        )
        ctx.w_transposed = _is_transposed_stack(weight)
        return _grouped_mm_triton_impl(inputs, weight, offsets)

    @staticmethod
    def backward(ctx, grad):
        x, w, offs = ctx.saved_tensors
        if torch.is_grad_enabled():
            return _grouped_mm_differentiable_backward(ctx, x, w, offs, grad)
        gx = gw = None
        if ctx.needs_input_grad[0]:
            gx = _grouped_mm_triton_impl(grad, w.transpose(-2, -1), offs)
        if ctx.needs_input_grad[1]:
            gw = _wgrad_in_weight_layout(_grouped_mm_triton_wgrad_impl, x, grad, offs, ctx.w_transposed)
        return gx, gw, None


def _grouped_mm_differentiable_backward(ctx, x, w, offs, grad):
    # create_graph=True: the raw kernels would detach the grads, so take torch._grouped_mm (double backward).
    gx = _grouped_mm_eager(grad, w.transpose(-2, -1), offs) if ctx.needs_input_grad[0] else None
    gw = _grouped_mm_fp16_wgrad_eager(x, grad, offs) if ctx.needs_input_grad[1] else None
    return gx, gw, None


def _triton_grouped_mm(inputs, weight, offsets):
    """torch._grouped_mm on the Triton kernels: custom op when traced, autograd.Function in eager."""
    if torch.compiler.is_compiling():
        return _GROUPED_MM_TRITON_OP(inputs, weight, offsets)
    return _GroupedMMTriton.apply(inputs, weight, offsets)


def _register_grouped_mm_triton_op():
    """torch._grouped_mm(inputs [M, K], weight [E, K, N], offs = int32 cumulative ends) on moe_grouped_fp16's Triton
    kernels as an opaque op; counts come from device offsets (no host sync); rows past offs[-1] stay unwritten, as in
    torch._grouped_mm."""
    if not hasattr(torch, "library") or not hasattr(torch.library, "custom_op"):
        return None
    try:
        return torch.ops.unsloth_zoo.grouped_mm_triton.default
    except (AttributeError, RuntimeError):
        pass
    try:
        @torch.library.custom_op("unsloth_zoo::grouped_mm_triton", mutates_args = ())
        def grouped_mm_triton(inputs: torch.Tensor, weight: torch.Tensor, offsets: torch.Tensor) -> torch.Tensor:
            return _grouped_mm_triton_impl(inputs, weight, offsets)

        @grouped_mm_triton.register_fake
        def _(inputs, weight, offsets):
            return inputs.new_empty((inputs.shape[0], weight.shape[-1]))

        @torch.library.custom_op("unsloth_zoo::grouped_mm_triton_wgrad", mutates_args = ())
        def grouped_mm_triton_wgrad(inputs: torch.Tensor, grad: torch.Tensor, offsets: torch.Tensor) -> torch.Tensor:
            return _grouped_mm_triton_wgrad_impl(inputs, grad, offsets)

        @grouped_mm_triton_wgrad.register_fake
        def _(inputs, grad, offsets):
            return inputs.new_empty((offsets.shape[0], inputs.shape[1], grad.shape[1]))

        def _setup_context(ctx, inputs, output):
            x, w, offs = inputs
            # Only what each gradient reads: a frozen base keeps no activation alive for a dW it never takes.
            ctx.save_for_backward(x if w.requires_grad else None, w if x.requires_grad else None, offs)
            ctx.w_transposed = _is_transposed_stack(w)

        def _backward(ctx, grad):
            x, w, offs = ctx.saved_tensors
            if torch.is_grad_enabled():
                return _grouped_mm_differentiable_backward(ctx, x, w, offs, grad)
            gx = gw = None
            if ctx.needs_input_grad[0]:
                gx = torch.ops.unsloth_zoo.grouped_mm_triton(grad, w.transpose(-2, -1), offs)
            if ctx.needs_input_grad[1]:
                gw = _wgrad_in_weight_layout(
                    torch.ops.unsloth_zoo.grouped_mm_triton_wgrad, x, grad, offs, ctx.w_transposed,
                )
            return gx, gw, None

        grouped_mm_triton.register_autograd(_backward, setup_context = _setup_context)
        return torch.ops.unsloth_zoo.grouped_mm_triton.default
    except Exception:
        return None


_GROUPED_MM_TRITON_OP = _register_grouped_mm_triton_op()


def _grouped_matmul_loop(inputs, weight, offsets, bounds = None):
    """Per-group loop out[s:e] = inputs[s:e] @ weight[g] with no autograd; bounds are pre-decoded group ends, since
    re-reading offsets would add a second stream sync per grouped matmul."""
    _count_grouped_mm_sync("loop")
    outputs = []
    start = 0
    if bounds is None: bounds = offsets.detach().cpu().tolist()
    for expert_idx, end in enumerate(bounds):
        if start < end:
            outputs.append(torch.matmul(inputs[start:end], weight[expert_idx]))
        start = end
    if outputs:
        return torch.cat(outputs, dim=0)
    return inputs.new_empty((0, weight.shape[-1]))


# Projection strides for the routing signature: a checksum, not an identity, since four projections leave a hidden - 4
# null space; an identity would copy the [T, hidden] input (512MB transient); a swap must match every term (each
# weighted by row index) and the norm.
_SIGNATURE_STRIDES = (12.9898, 78.233, 43.7585, 96.4271)

# Row 2-norm carried beside the projections; it is not linear in the row, so the projections' null space does not reach
# it, and swapped rows must match norms too.
_SIGNATURE_EXTRA = 1

# Trailing checksum entries of a packed signature, not group boundaries; named because offsets are sliced off, and a bare [:-1] would read them as experts.
_SIGNATURE_WIDTH = len(_SIGNATURE_STRIDES) + _SIGNATURE_EXTRA


def _routing_signature(inputs, offsets):
    """Offsets plus an order-sensitive checksum: a fixed pseudo-random projection of the sorted rows (not a sum) so
    swaps between equal-sized experts show; it depends only on hidden size, so forward and recompute agree; the
    matvec runs in the input dtype with no FP32 copy."""
    inputs = inputs.detach()
    hidden = inputs.shape[-1]
    # Autocast explicitly off: mv/mm are on autocast's lower-precision list and only one of forward/backward saw it, so
    # fp32 inputs hashed differently and backward raised a spurious routing error.
    with torch.autocast(device_type = inputs.device.type, enabled = False):
        weights = torch.linspace(
            1.0, 2.0, hidden, device = inputs.device, dtype = torch.float32)
        # Irrational stride: a linear ramp alone sums the same under a reversal.
        strides = torch.tensor(
            _SIGNATURE_STRIDES, device = inputs.device, dtype = torch.float32)
        weights = torch.sin(
            weights.unsqueeze(1) * strides).to(inputs.dtype)
        # Several projections, not one: a single dot maps rows orthogonal to it to zero like the zero row, letting such swaps across an expert boundary pass.
        rows = (inputs @ weights).float()
        # Norm is not linear, so the projections' null space cannot reach it; vector_norm accumulates in fp32 from the
        # input dtype, avoiding three concurrent 512MB temporaries of an x.float() product at 32K by 4096; dtype is
        # promoted, not pinned, since vector_norm rejects narrowing.
        norm = torch.linalg.vector_norm(
            inputs, dim = -1, keepdim = True,
            dtype = torch.promote_types(inputs.dtype, torch.float32))
        rows = torch.cat((rows, norm.to(rows.dtype)), -1)
        ramp = torch.arange(
            1, rows.shape[0] + 1, device = rows.device, dtype = rows.dtype)
        checksum = (rows * ramp.unsqueeze(1)).sum(0)
    packed = torch.cat((
        offsets.detach().reshape(-1).to(torch.int64),
        checksum.view(torch.int32).to(torch.int64),
    ))
    return packed.cpu().tolist()


class _ManualGroupedMM(torch.autograd.Function):
    """Saves only inputs, weight and offsets, not per-group slices, since non-reentrant checkpoint replay raises
    CheckpointError when routing changes saved shapes; it does not make routing deterministic."""
    @staticmethod
    def forward(ctx, inputs, weight, offsets):
        # Stored as a plain list, not a tensor: non-reentrant checkpointing swaps saved tensors for the replay's, so
        # only this copy keeps the forward's routing for backward to compare.
        ctx.forward_routing = routing = _routing_signature(inputs, offsets)
        ctx.save_for_backward(inputs, weight, offsets)
        with torch.no_grad():
            return _grouped_matmul_loop(
                inputs, weight, offsets, routing[:-_SIGNATURE_WIDTH])

    @staticmethod
    def backward(ctx, grad_output):
        inputs, weight, offsets = ctx.saved_tensors
        routing = _routing_signature(inputs, offsets)
        if routing != ctx.forward_routing:
            # Raises louder than CheckpointError: shape-stable saves would let a reroute pass silently, and pairing
            # grad_output with the replay's partition gives a gradient for routing that never made the loss.
            were = ctx.forward_routing[:-_SIGNATURE_WIDTH]
            now = routing[:-_SIGNATURE_WIDTH]
            how = ("the same experts in a different order"
                   if were == now else f"expert ends {were} then {now}")
            raise RuntimeError(
                "Unsloth: the MoE router assigned tokens differently in the "
                f"activation-checkpoint replay than in the forward ({how}), so "
                "the gradients would belong to a routing that never produced "
                "the loss. Turn gradient checkpointing off for this run, or "
                "make the router deterministic."
            )
        bounds = routing[:-_SIGNATURE_WIDTH]
        _count_grouped_mm_sync("loop")
        need_x, need_w, _ = ctx.needs_input_grad
        grad_output = grad_output.contiguous()
        # Backward runs outside the forward's autocast, so grad_output can be bf16 while saved tensors are fp32; dtypes
        # are aligned by hand since custom_fwd/custom_bwd fix device_type at class definition, and this also runs on CPU
        # and XPU.
        compute_dtype = grad_output.dtype
        grad_inputs = torch.zeros_like(inputs) if need_x else None
        grad_weight = torch.zeros_like(weight) if need_w else None
        # Writes groups in place via out= only without a cast, with a contiguous destination, and grad mode off, since
        # out= raises under create_graph=True; the plain path stays differentiable.
        direct = (
            not torch.is_grad_enabled()
            and inputs.dtype == weight.dtype == compute_dtype
            and (grad_inputs is None or grad_inputs.is_contiguous())
            and (grad_weight is None or grad_weight.is_contiguous())
        )
        start = 0
        for expert_idx, end in enumerate(bounds):
            if start < end:
                g = grad_output[start:end]
                if need_x:
                    w = weight[expert_idx]
                    if direct:
                        torch.matmul(g, w.transpose(-2, -1),
                                     out = grad_inputs[start:end])
                    else:
                        grad_inputs[start:end] = (
                            g @ w.to(compute_dtype).transpose(-2, -1)
                        ).to(inputs.dtype)
                if need_w:
                    if direct:
                        torch.matmul(inputs[start:end].transpose(-2, -1), g,
                                     out = grad_weight[expert_idx])
                    else:
                        x = inputs[start:end].to(compute_dtype)
                        grad_weight[expert_idx] = (
                            x.transpose(-2, -1) @ g).to(weight.dtype)
            start = end
        return grad_inputs, grad_weight, None


def _manual_grouped_mm(
    inputs: torch.Tensor, weight: torch.Tensor, offsets: torch.Tensor
) -> torch.Tensor:
    """Marked torch.compiler.disable because group bounds come from a tensor (a data-dependent start < end branch);
    under fullgraph=True the break is fatal, so the eager fallback in temporary_patches/utils.py is needed."""
    # Grad off skips the signature (no autograd node reads it). KNOWN GAP: a reentrant checkpoint runs its forward with
    # grad off and its replay with grad on, so a reroute passes silently; closing it needs unsloth_checkpoint to
    # announce its region and call order; non-reentrant is unaffected.
    if not torch.is_grad_enabled():
        return _grouped_matmul_loop(inputs, weight, offsets)
    return _ManualGroupedMM.apply(inputs, weight, offsets)


if hasattr(torch, "compiler") and hasattr(torch.compiler, "disable"):
    _manual_grouped_mm = torch.compiler.disable(_manual_grouped_mm)
_manual_grouped_mm_eager = _manual_grouped_mm


def _manual_grouped_mm_dtype(inputs, weight, autocast_dtype):
    """The dtype the loop's matmuls return: autocast casts floating operands except float64."""
    def cast(t):
        if autocast_dtype is not None and t.is_floating_point() and t.dtype != torch.float64:
            return autocast_dtype
        return t.dtype
    return torch.promote_types(cast(inputs), cast(weight))


def _register_manual_grouped_mm_op():
    """Per-group loop as an opaque custom op so no-grad compiled frames do not graph break; None if unsupported."""
    if not hasattr(torch, "library") or not hasattr(torch.library, "custom_op"):
        return None
    try:
        return torch.ops.unsloth_zoo.manual_grouped_mm.default
    except (AttributeError, RuntimeError):
        pass
    # The op reads group bounds on the host (a sync), so a CUDA graph must not capture it.
    tags = {}
    if hasattr(torch, "Tag") and hasattr(torch.Tag, "cudagraph_unsafe"):
        import inspect
        if "tags" in inspect.signature(torch.library.custom_op).parameters:
            tags = {"tags": (torch.Tag.cudagraph_unsafe,)}
    try:
        @torch.library.custom_op("unsloth_zoo::manual_grouped_mm", mutates_args = (), **tags)
        def manual_grouped_mm(
            inputs: torch.Tensor, weight: torch.Tensor, offsets: torch.Tensor, autocast_dtype: Optional[torch.dtype],
        ) -> torch.Tensor:
            ctx = (
                torch.autocast(inputs.device.type, dtype = autocast_dtype)
                if autocast_dtype is not None else contextlib.nullcontext()
            )
            with torch.no_grad(), ctx:
                out = _grouped_matmul_loop(inputs, weight, offsets)
                if out.shape[0] != inputs.shape[0]:  # rows past the last group: zero, as torch._grouped_mm
                    out = torch.cat((out, out.new_zeros((inputs.shape[0] - out.shape[0], out.shape[1]))))
            # All-empty groups run no matmul; match the fake's dtype.
            return out.to(_manual_grouped_mm_dtype(inputs, weight, autocast_dtype))

        @manual_grouped_mm.register_fake
        def _(inputs, weight, offsets, autocast_dtype):
            dtype = _manual_grouped_mm_dtype(inputs, weight, autocast_dtype)
            return inputs.new_empty((inputs.shape[0], weight.shape[-1]), dtype = dtype)

        return torch.ops.unsloth_zoo.manual_grouped_mm.default
    except Exception:
        return None


_MANUAL_GROUPED_MM_OP = _register_manual_grouped_mm_op()


def _autocast_dtype(device_type):
    try:
        if torch.is_autocast_enabled(device_type):
            return torch.get_autocast_dtype(device_type)
    except (AttributeError, RuntimeError, TypeError):
        pass
    return None


def _manual_grouped_mm(inputs: torch.Tensor, weight: torch.Tensor, offsets: torch.Tensor) -> torch.Tensor:
    """Compiled no-grad calls use the opaque op; others use the eager loop, whose ctx-held routing list (not a tensor)
    survives non-reentrant checkpoint replay, so rerouting still raises."""
    if (
        _MANUAL_GROUPED_MM_OP is not None
        and torch.compiler.is_compiling()
        and not (torch.is_grad_enabled() and (inputs.requires_grad or weight.requires_grad))
    ):
        if inputs.shape[0] == 0:  # eager keeps the input dtype
            return inputs.new_empty((0, weight.shape[-1]))
        return _MANUAL_GROUPED_MM_OP(inputs, weight, offsets, _autocast_dtype(inputs.device.type))
    return _manual_grouped_mm_eager(inputs, weight, offsets)


# Recomputes the frozen base expert GEMM in backward by rebuilding the bf16 stack from 4-bit Params4bit (dX only; LoRA
# stays a separate grouped_mm), instead of pinning it on the tape; see _moe_recompute_enabled.


def _base_is_recomputable(source) -> bool:
    """True only for a frozen, grouped-mm capable base that can be rebuilt in backward; trainable or unsupported bases must use the pinned path."""
    try:
        if not _should_use_separated_lora():          # merged LoRA folds the delta into base
            return False
        if not _check_torch_grouped_mm_supported():
            return False
        param = source
        while hasattr(param, "base_layer"):
            param = param.base_layer
        if HAS_BNB and Params4bit is not None and isinstance(param, Params4bit):
            if getattr(param, "quant_state", None) is None:
                return False
            return not param.requires_grad
        if is_packed_expert_param(param):
            return not param.requires_grad
        if isinstance(param, torch.Tensor):
            return (not param.requires_grad) and param.dtype in (
                torch.bfloat16, torch.float16, torch.float32,
            )
    except Exception:
        return False
    return False


def _moe_recompute_default(prefer_memory: bool = False) -> bool:
    """Pin-vs-recompute decision independent of the source weight.

    Adaptive by default: pin (return False) inside a gradient-checkpoint recompute
    pass, where the stack is rebuilt immediately before the layer's own backward so
    the pin is momentary and cheap; otherwise recompute (return True), so a
    non-checkpointed forward does not hold every layer's dense stack across the whole
    backward. UNSLOTH_MOE_RECOMPUTE overrides it: "1" forces recompute (max memory
    saving), "0" forces pinning (max speed for memory-rich runs).

    ``prefer_memory`` biases the no-override case toward recompute even inside a GC
    recompute pass. It is set for bases whose pinned form is a large dense dequant of
    a compressed weight (bnb 4-bit MoE experts): there the "momentary" pin still
    materializes the full bf16 expert stack the 4-bit storage exists to avoid, which
    can be several GiB per layer on large MoEs, so recompute is the better default
    when the model is already memory-constrained (4-bit + gradient checkpointing).

    The GC branch reads a thread-local; under torch.compile of the MoE forward that
    read can be traced away and frozen at the first trace, so the adaptive choice may
    not re-evaluate per GC pass. That only trades memory for speed (pin and recompute
    are dX-identical), never correctness, and the grouped GEMM path generally runs
    eager anyway; set UNSLOTH_MOE_RECOMPUTE explicitly to pin the choice if needed."""
    override = os.environ.get("UNSLOTH_MOE_RECOMPUTE")
    if override == "1":
        return True
    if override == "0":
        return False
    if prefer_memory:
        return True
    try:
        from unsloth_zoo.gradient_checkpointing import in_gradient_checkpoint_recompute
        return not in_gradient_checkpoint_recompute()
    except Exception:
        return True  # safe default: recompute rather than pin across a full backward


def _source_pins_large_dequant(source) -> bool:
    """True for a bnb 4-bit MoE base, where pinning would hold a full dense dequant (recompute is the memory-preserving
    default under gradient checkpointing); plain bf16/fp16/fp32 bases pin their own storage and keep the adaptive
    policy."""
    if not (HAS_BNB and Params4bit is not None):
        return False
    try:
        param = source
        while hasattr(param, "base_layer"):
            param = param.base_layer
        return isinstance(param, Params4bit) and getattr(param, "quant_state", None) is not None
    except Exception:
        return False


def _in_gc_recompute() -> bool:
    try:
        from unsloth_zoo.gradient_checkpointing import in_gradient_checkpoint_recompute
        return bool(in_gradient_checkpoint_recompute())
    except Exception:
        return False


_MOMENTARY_PIN_HEADROOM = 2.0   # free memory must cover this many copies of one layer's stack


def _momentary_pin_fits(source, dtype = None) -> bool:
    """Whether one layer's dequantized stack fits in free + cached-unused memory; unmeasurable means False."""
    try:
        param = source
        while hasattr(param, "base_layer"):
            param = param.base_layer
        device = param.device
        backend = getattr(torch, device.type, None) if device.type in ("cuda", "xpu") else None
        if backend is None or not callable(getattr(backend, "mem_get_info", None)):
            return False
        shape = _logical_expert_shape(param)
        if not shape:
            return False
        dtype = dtype or getattr(getattr(param, "quant_state", None), "dtype", None) or torch.bfloat16
        need = math.prod(int(d) for d in shape) * dtype.itemsize
        # Cached briefly: mem_get_info per source per replay costs more than the dequant it saves.
        key = (device.type, device.index, need, _MOMENTARY_PIN_HEADROOM)
        now = time.monotonic()
        hit = _MOMENTARY_PIN_FITS_CACHE.get(key)
        if hit is not None and now - hit[1] < _MOMENTARY_PIN_FITS_TTL_S:
            return hit[0]
        free, _ = backend.mem_get_info(device)
        free += backend.memory_reserved(device) - backend.memory_allocated(device)
        fits = free >= _MOMENTARY_PIN_HEADROOM * need
        _MOMENTARY_PIN_FITS_CACHE[key] = (fits, now)
        return fits
    except Exception:
        return False


_MOMENTARY_PIN_FITS_CACHE = {}
_MOMENTARY_PIN_FITS_TTL_S = 0.5


def _moe_recompute_enabled(source, dtype = None) -> bool:
    """Recompute the dequantized base stack in backward (True) or pin it (False); only frozen grouped-mm bases
    recompute. bnb 4-bit recomputes unless UNSLOTH_MOE_GC_REPLAY_PIN=1 and the stack fits in a checkpoint replay
    (pinning then saves a dequant but raises peak memory)."""
    if not _base_is_recomputable(source):
        return False
    override = os.environ.get("UNSLOTH_MOE_RECOMPUTE")
    if override == "1":
        return True
    if override == "0":
        return False
    if _source_pins_large_dequant(source):
        if (
            os.environ.get("UNSLOTH_MOE_GC_REPLAY_PIN") == "1"
            and _in_gc_recompute()
            and _momentary_pin_fits(source, dtype = dtype)
        ):
            return False
        return True
    return _moe_recompute_default()


class _GroupedMMRecompute(torch.autograd.Function):
    """grouped_mm(inputs, W) with W from weight_provider(): saves only offsets and rebuilds W in backward (for dX only) instead of pinning the dense stack."""

    @staticmethod
    def forward(ctx, inputs, offsets, weight_provider):
        ctx.weight_provider = weight_provider
        ctx.save_for_backward(offsets)   # inputs is unused in backward (frozen base -> dX only)
        with torch.no_grad():
            out = _grouped_mm_with_backward_fix(inputs, weight_provider(), offsets)
        return out

    @staticmethod
    def backward(ctx, grad_output):
        (offsets,) = ctx.saved_tensors
        with torch.no_grad():
            transposed = getattr(ctx.weight_provider, "transposed", None)
            # The view, not a copy: _grouped_mm_with_backward_fix copies only where the view path is unproven.
            weight_t = transposed() if transposed is not None else ctx.weight_provider().transpose(-2, -1)
            grad_input = _grouped_mm_with_backward_fix(grad_output.contiguous(), weight_t, offsets)
        return grad_input, None, None


_EXPERT_BIAS_ONE_HOT_ELEMENTS = 1 << 24


class _ExpertBiasGather(torch.autograd.Function):
    """Gathers bias by expert id; backward is one-hot(expert_ids) @ grad as one fp32-accumulating GEMM, since a 16-bit
    index_add_ is CAS-emulated on sm80 and rounds each partial sum."""

    @staticmethod
    def forward(ctx, bias, expert_ids):
        ctx.save_for_backward(expert_ids)
        ctx.num_experts = bias.shape[0]
        return bias.index_select(0, expert_ids)

    @staticmethod
    def backward(ctx, grad):
        (expert_ids,) = ctx.saved_tensors
        experts = torch.arange(ctx.num_experts, device = expert_ids.device, dtype = expert_ids.dtype).unsqueeze(1)
        # The one-hot is at most _EXPERT_BIAS_ONE_HOT_ELEMENTS: long contexts go in row chunks, summed in fp32.
        chunk = max(1, _EXPERT_BIAS_ONE_HOT_ELEMENTS // ctx.num_experts)
        rows = grad.shape[0]
        # Autocast off: under fp16 autocast, including compiled backward's same_as_forward, mm rounds the per-expert sum
        # of fp32 grads to fp16 and overflows past 65504.
        with torch.autocast(device_type = grad.device.type, enabled = False):
            if rows <= chunk:
                return (expert_ids.unsqueeze(0) == experts).to(grad.dtype) @ grad, None
            # GEMMs only (no index_add_ atomics) for reproducibility; fp32 partials, since 16-bit chunk sums can overflow to inf.
            if torch.compiler.is_compiling():
                if _EXPERT_BIAS_GRAD_OP is not None and grad.dtype in (torch.float16, torch.bfloat16) \
                        and not _mm_fp32_out_ok(grad):
                    # The fallback would upcast all of grad to fp32; running the eager row chunks as an opaque op keeps
                    # that copy capped without specializing the row count.
                    return _EXPERT_BIAS_GRAD_OP(expert_ids, grad, ctx.num_experts), None
                # A loop over symbolic rows would specialize them: one uncapped GEMM instead.
                return _one_hot_mm_fp32(expert_ids.unsqueeze(0) == experts, grad).to(grad.dtype), None
            return _expert_bias_grad_chunked(expert_ids, grad, ctx.num_experts), None


def _expert_bias_grad_chunked(expert_ids, grad, num_experts):
    """one_hot(expert_ids) @ grad in row chunks, summed in fp32; the one-hot and any fp32 grad copy stay capped."""
    experts = torch.arange(num_experts, device = expert_ids.device, dtype = expert_ids.dtype).unsqueeze(1)
    chunk = max(1, _EXPERT_BIAS_ONE_HOT_ELEMENTS // num_experts)
    if not _mm_fp32_out_ok(grad):
        # The fallback upcasts each grad chunk to fp32: cap that copy too.
        chunk = max(1, _EXPERT_BIAS_ONE_HOT_ELEMENTS // max(num_experts, grad.shape[1]))
    out = torch.zeros(num_experts, grad.shape[1], dtype = torch.float32, device = grad.device)
    with torch.autocast(device_type = grad.device.type, enabled = False):
        for start in range(0, grad.shape[0], chunk):
            out += _one_hot_mm_fp32(expert_ids[start : start + chunk].unsqueeze(0) == experts, grad[start : start + chunk])
    return out.to(grad.dtype)


def _register_expert_bias_grad_op():
    """Opaque op wrapping _expert_bias_grad_chunked for compiled backwards: chunks over the real row count so tracing
    neither specializes rows nor copies grad to fp32; registered once per process."""
    if not hasattr(torch, "library") or not hasattr(torch.library, "custom_op"):
        return None
    try:
        return torch.ops.unsloth_zoo.expert_bias_grad.default
    except (AttributeError, RuntimeError):
        pass
    try:
        @torch.library.custom_op("unsloth_zoo::expert_bias_grad", mutates_args = ())
        def expert_bias_grad(expert_ids: torch.Tensor, grad: torch.Tensor, num_experts: int) -> torch.Tensor:
            return _expert_bias_grad_chunked(expert_ids, grad, num_experts)

        @expert_bias_grad.register_fake
        def _(expert_ids, grad, num_experts):
            return grad.new_empty((num_experts, grad.shape[1]))

        return torch.ops.unsloth_zoo.expert_bias_grad.default
    except Exception:
        return None


# torch.mm(..., out_dtype = torch.float32): 16-bit inputs, fp32 output (aten::mm.dtype, CUDA only, torch 2.9+).
_MM_OUT_DTYPE = "dtype" in torch.ops.aten.mm.overloads()


def _mm_fp32_out_ok(grad):
    return _MM_OUT_DTYPE and grad.is_cuda and not is_rocm_torch(torch) and grad.dtype in (torch.float16, torch.bfloat16)


def _one_hot_mm_fp32(one_hot, grad):
    """one_hot (bool [E, rows]) @ grad as fp32 [E, D], with no 16-bit rounding of the sum."""
    if grad.dtype == torch.float32:
        return one_hot.to(grad.dtype) @ grad
    if _mm_fp32_out_ok(grad):
        return torch.mm(one_hot.to(grad.dtype), grad, out_dtype = torch.float32)
    return one_hot.to(torch.float32) @ grad.float()


_EXPERT_BIAS_GRAD_OP = _register_expert_bias_grad_op()


def _gather_expert_bias(bias, expert_ids):
    expert_ids = expert_ids.to(bias.device)
    if bias.requires_grad and torch.is_grad_enabled() and bias.dim() == 2:
        return _ExpertBiasGather.apply(bias, expert_ids)
    return bias.index_select(0, expert_ids)


def _base_grouped_mm(inputs, offsets, weight_provider, recompute, plan = None):
    """With recompute, rebuild W in backward (only the planned experts, chunk by chunk, when a plan is given); otherwise use the eager grouped_mm."""
    if recompute:
        if plan is not None:
            return _GroupedMMSelectiveRecompute.apply(inputs, weight_provider, plan)
        return _GroupedMMRecompute.apply(inputs, offsets, weight_provider)
    return _grouped_mm_with_backward_fix(inputs, weight_provider(), offsets)


def _lora_fold_base_mm(inputs, offsets, weight_provider, recompute, lora, source):
    """Base grouped GEMM with the separated LoRA folded in (moe_lora_fold), or None to keep the separated path."""
    try:
        from unsloth_zoo.temporary_patches.moe_lora_fold import lora_fold_base_mm
    except ImportError:
        return None
    return lora_fold_base_mm(inputs, offsets, weight_provider, recompute, lora, source)


def _gc_moe_checkpoint_call():
    """(routing frame, entry index, replaying) for this experts call inside an Unsloth checkpoint, else None (eager only)."""
    if torch.compiler.is_compiling():
        return None
    try:
        from unsloth_zoo.gradient_checkpointing import moe_checkpoint_call
    except ImportError:
        return None
    return moe_checkpoint_call()


def _gc_keep_base_slot(module, checkpoint_call = None):
    if torch.compiler.is_compiling() or checkpoint_call is None:
        return None
    try:
        from unsloth_zoo.temporary_patches.moe_gc_keep_base import keep_base_slot
    except ImportError:
        return None
    return keep_base_slot(module, checkpoint_call)


def _moe_base_and_lora(inputs, offsets, weight_provider, recompute, plan, lora, source, keep_slot, proj):
    """One projection's base grouped GEMM: (output, LoRA still to add). Kept-base replay first, then the LoRA fold,
    else the plain base GEMM with the LoRA left to the separated path. Traced code never keeps (the checkpoint
    state would be frozen at trace time); the fold traces through its opaque op."""
    if keep_slot is not None and plan is None and not torch.compiler.is_compiling():
        try:
            from unsloth_zoo.temporary_patches.moe_gc_keep_base import kept_base_mm
        except ImportError:
            kept_base_mm = None
        found = None if kept_base_mm is None else kept_base_mm(
            inputs, offsets, weight_provider, recompute, lora, source, keep_slot, proj,
        )
        if found is not None:
            return found
    if lora is not None and plan is None:
        out = _lora_fold_base_mm(inputs, offsets, weight_provider, recompute, lora, source)
        if out is not None:
            return out, None
    return _base_grouped_mm(inputs, offsets, weight_provider, recompute, plan), lora


def _nf4_fused_base_mm(inputs, offsets, source, proj_type, hidden_dim, model_type, experts_module):
    """UNSLOTH_MOE_NF4_FUSED grouped GEMM on a frozen NF4 stack; None keeps the dequant path."""
    if os.environ.get("UNSLOTH_MOE_NF4_FUSED", "0") in ("", "0") or not _base_is_recomputable(source):
        return None
    cache = _expert_cache_module()
    if cache is not None:
        # The param the dequant path decodes (_get_base_weight unwrapping), in the dtype it will ask for.
        param = source
        while hasattr(param, "base_layer"):
            param = param.base_layer
        if not isinstance(param, torch.Tensor) and hasattr(param, "weight"):
            param = param.weight
        if _expert_cache_get(cache, param, inputs.dtype, count = False) is not None:
            return None   # a cached 16-bit stack makes the dequant path's decode free
    try:
        from unsloth_zoo.temporary_patches.moe_nf4_grouped import maybe_nf4_grouped_mm, nf4_auto_fused, nf4_fused_mode
    except ImportError:
        return None
    if (
        not torch.compiler.is_compiling() and nf4_fused_mode() == "auto"
        and not nf4_auto_fused(inputs.shape[0], offsets.shape[0], inputs.device)
    ):
        # Eager has no recompile to avoid: above the cap take the regular dequant path, where the LoRA fold and the
        # kept checkpoint base apply (the in-op dequant branch has neither).
        return None
    preprocess = lambda w: preprocess_weight(w, proj_type, hidden_dim, model_type, experts_module = experts_module)
    return maybe_nf4_grouped_mm(inputs, offsets, source, preprocess)


# UNSLOTH_MOE_SELECTIVE_DEQUANT: auto = num_rows experts (sync-free) if rows <= 7/8 E; 1 = exact routed set (one host sync); 0 = full stack.
SELECTIVE_DEQUANT_STATS = {"plans": 0, "dequant_calls": 0, "experts_dequantized": 0, "experts_total": 0}


class _SelectiveDequantPlan:
    __slots__ = ("num_experts", "num_rows", "chunks")

    def __init__(self, num_experts, num_rows, chunks):
        self.num_experts = num_experts
        self.num_rows = num_rows
        self.chunks = chunks   # [(expert slice or int64 ids, row_lo, row_hi, offsets relative to row_lo)]


def _selective_dequant_chunk_experts() -> int:
    try:
        return max(int(os.environ.get("UNSLOTH_MOE_DEQUANT_CHUNK_EXPERTS", "0")), 0)
    except ValueError:
        return 0


_DEVICE_TOTAL_BYTES = {}


def _cuda_capturing(device):
    """Whether `device`'s current stream is capturing a CUDA graph (is_current_stream_capturing alone asks the
    current device, which a split-device model need not have switched to the operand's)."""
    if device.type != "cuda":
        return False
    with torch.cuda.device(device):
        return torch.cuda.is_current_stream_capturing()


def _auto_dequant_cap_source(experts_module):
    """(cap from UNSLOTH_MOE_DEQUANT_MAX_MB in bytes or None, class scratch fraction or None); both None means no
    automatic cap applies. Reads no tensor, so unflagged models pay nothing beyond two lookups."""
    if "UNSLOTH_MOE_DEQUANT_CHUNK_EXPERTS" in os.environ:
        return None, None   # an explicit chunk setting wins, 0 included
    raw = os.environ.get("UNSLOTH_MOE_DEQUANT_MAX_MB", "auto").strip().lower()
    if raw not in ("", "auto"):
        try:
            cap = float(raw) * 2**20
        except ValueError:
            return None, None
        return (cap if cap > 0 else None), None
    fraction = getattr(experts_module, "_unsloth_dequant_scratch_fraction", None)
    return None, (float(fraction) if fraction else None)


def _device_headroom_bytes(index):
    """(driver free bytes on cuda:index, callable adding the allocator's reserved but unused blocks, which it releases
    and retries with before failing). The allocator stats are read only when the driver reading alone is short; both
    cost host time (mem_get_info ~0.2 ms), never a device sync."""
    free = torch.cuda.mem_get_info(index)[0]
    return free, lambda: free + max(torch.cuda.memory_reserved(index) - torch.cuda.memory_allocated(index), 0)


class _TorchCheckpointRecord:
    """Chunk decisions of one torch non-reentrant checkpoint frame: dequant_chunks keyed (nth call, module) by the
    forward, and a per-module call count for the forward (gid None) and each recompute (its graph task id)."""
    def __init__(self):
        self.dequant_chunks = {}
        self.counts = {}


def _torch_checkpoint_call(experts_module):
    """(record, call, replaying) shaped like moe_checkpoint_call when this call runs inside torch's own non-reentrant
    checkpoint: its forward (top saved-tensors hook packs into `frame`) or its recompute (packs into
    `target_frame_ref` for graph task `gid`). The decision lives on that frame, so each in-flight checkpoint and each
    backward of it matches its own forward. None on older torch, other hooks on top, or no checkpoint."""
    top = getattr(torch._C._autograd, "_top_saved_tensors_default_hooks", None)
    if top is None:
        return None
    try:
        hooks = top(True)
        if not hooks:
            return None
        pack = inspect.unwrap(hooks[0])
        cells = dict(zip(pack.__code__.co_freevars, pack.__closure__ or ()))
        if "frame" in cells:
            frame, gid = cells["frame"].cell_contents, None
        elif "target_frame_ref" in cells and "gid" in cells:
            frame, gid = cells["target_frame_ref"].cell_contents(), cells["gid"].cell_contents
        else:
            return None
    except (AttributeError, TypeError, ValueError):
        return None
    if frame is None or not hasattr(frame, "weak_holders"):
        return None
    record = getattr(frame, "_unsloth_dequant_record", None)
    if record is None:
        record = frame._unsloth_dequant_record = _TorchCheckpointRecord()
    counts = record.counts.setdefault(gid, {})
    call = counts.get(id(experts_module), 0)
    counts[id(experts_module)] = call + 1
    return record, call, gid is not None


def _auto_dequant_chunk_experts(splits, dtype, experts_module, device, experts_needed = None, checkpoint_call = None) -> int:
    """_auto_dequant_decide_chunk, decided once per checkpointed experts call: the first pass records its decision on
    the call's routing frame and that call's replay (every backward of it) takes exactly that decision back, whatever
    the headroom or other layers read since, so the replay runs the same plan, kept base and LoRA fold as its first
    pass. torch's non-reentrant checkpoint (no routing frame) gets the same on its own frame. Calls outside a checkpoint
    (or a replay with no recorded decision) decide fresh."""
    record = key = None
    if checkpoint_call is None:
        checkpoint_call = _torch_checkpoint_call(experts_module)
    if checkpoint_call is not None:
        frame, call, replaying = checkpoint_call
        record = getattr(frame, "dequant_chunks", None)
        key = (call, id(experts_module))
        if record is not None and replaying and key in record:
            return record[key]
        if replaying:
            record = None   # never let a replay overwrite (or create) its first pass's decision
    chunk = _auto_dequant_decide_chunk(splits, dtype, experts_module, device, experts_needed)
    if record is not None:
        record[key] = chunk
    return chunk


def _auto_dequant_decide_chunk(splits, dtype, experts_module, device, experts_needed = None) -> int:
    """Experts per chunk keeping one projection's dequantized scratch under a cap, or 0 for the unchunked plan.

    `experts_needed` is how many experts the unchunked plan reads (the sync-free capped plan's rows, else the whole
    stack E); the scratch is that many experts of the largest projection.
    UNSLOTH_MOE_DEQUANT_MAX_MB set: a hard cap, chunk whenever the scratch exceeds it.
    Otherwise only experts classes declaring `_unsloth_dequant_scratch_fraction` (Inkling 2) take part, with a cap of
    that share of the card. Chunking costs a host sync per call and disables the kept checkpoint base, so it engages
    only on need: the scratch is over twice the cap AND it does not fit the device right now (twice the scratch, for
    the dequant plus a cast or transposed copy, plus one cap of slack, above the free memory). Every call reads again,
    so a transient shortfall clears once the stack fits; a checkpoint replay instead reuses its own first pass's
    decision (_auto_dequant_chunk_experts). Inkling-2-Mini's 1.27 GiB
    gate_up stack therefore stays whole on a 40 GB card without any query, and on 16 to 32 GB cards while memory is
    not short; Small's 16 GiB stack chunks wherever it does not fit. An explicit UNSLOTH_MOE_DEQUANT_CHUNK_EXPERTS (0 included) wins. Chunks read
    the same values as the whole stack."""
    cap, fraction = _auto_dequant_cap_source(experts_module)
    if cap is None and fraction is None:
        return 0
    if cap is None and device.type != "cuda":
        return 0
    element = torch.empty((), dtype = dtype).element_size()
    E = splits[0][0]
    needed = E if experts_needed is None else min(max(int(experts_needed), 0), E)
    per_expert = max(inner[0] * inner[1] for _, inner in splits) * element
    scratch = needed * per_expert
    if cap is not None:
        return 0 if scratch <= cap else max(1, int(cap // per_expert))
    index = device.index if device.index is not None else torch.cuda.current_device()
    total = _DEVICE_TOTAL_BYTES.get(index)
    if total is None:
        total = _DEVICE_TOTAL_BYTES[index] = torch.cuda.get_device_properties(index).total_memory
    cap = fraction * total
    if cap <= 0 or scratch <= 2 * cap:
        return 0
    want = 2 * scratch + cap
    free, with_cached = _device_headroom_bytes(index)
    if free >= want or with_cached() >= want:
        return 0
    return max(1, int(cap // per_expert))


def _bnb4bit_expert_split(param):
    """(E, per-expert shape) only when every expert owns whole packed elements and whole absmax blocks, so gathering experts is exact; None otherwise."""
    while hasattr(param, "base_layer"):
        param = param.base_layer
    if not (HAS_BNB and isinstance(param, Params4bit)):
        return None
    qs = getattr(param, "quant_state", None)
    if qs is None or param.requires_grad:
        return None
    shape = getattr(param, "_original_shape", None) or qs.shape
    if shape is None or len(shape) != 3:
        return None
    E, per_expert = int(shape[0]), int(shape[1]) * int(shape[2])
    weights_per_element = 2 * param.data.element_size()
    if E == 0 or per_expert == 0 or per_expert % qs.blocksize or per_expert % weights_per_element:
        return None
    if param.data.numel() * weights_per_element != E * per_expert or qs.absmax.numel() != E * (per_expert // qs.blocksize):
        return None
    return E, tuple(int(x) for x in shape[1:])


# Gathered ids decode in pieces of at least _SELECTIVE_GATHER_MIN experts and at most 1/8 of the request, keeping the
# packed copy near 1/32 of the fp16 output without a launch per expert.
_SELECTIVE_GATHER_PIECES = 8
_SELECTIVE_GATHER_MIN = 32


def _dequantize_bnb4bit_experts(param, experts, target_dtype = None):
    """Dequantize only `experts` of a packed 4-bit stack: a slice reads views of the packed bytes
    and absmax blocks, an int64 id tensor gathers them in a few pieces. Each piece is a smaller
    QuantState decoded by the same kernels, so every element matches the full-stack read."""
    cache = _expert_cache_module()
    if cache is None:
        return _dequantize_bnb4bit_experts_once(param, experts, target_dtype)
    # The cache may hold the memory this read needs (gather, decode or cast): drop it once and retry.
    return cache.with_expert_cache_oom_retry(lambda: _dequantize_bnb4bit_experts_once(param, experts, target_dtype))


def _dequantize_bnb4bit_experts_once(param, experts, target_dtype = None):
    from bitsandbytes.functional import QuantState

    while hasattr(param, "base_layer"):
        param = param.base_layer
    cache = _expert_cache_module()
    cached = _expert_cache_get(cache, param, target_dtype)
    if cached is not None:
        out = cached[experts] if isinstance(experts, slice) else cached.index_select(0, experts)
        return out.to(target_dtype) if target_dtype is not None else out
    E, inner = _bnb4bit_expert_split(param)
    qs = param.quant_state
    blocks = inner[0] * inner[1] // qs.blocksize
    packed_all = param.data.reshape(E, -1)
    absmax_all, offset, absmax2_all = qs.absmax, qs.offset, None
    if qs.nested:
        s2 = qs.state2
        if blocks % s2.blocksize == 0:
            absmax2_all = s2.absmax.reshape(E, -1)
        else:
            # Second-level blocks straddle experts: denest as bitsandbytes does (multiply, then
            # add the offset in fp32), which is what both 4-bit decoders compute per block.
            absmax_all = (bnb.functional.dequantize_blockwise(absmax_all, s2) + offset).float()
            offset = None
    absmax_all = absmax_all.reshape(E, blocks)

    if isinstance(experts, slice):
        n = len(range(*experts.indices(E)))
        pieces = [experts]
    else:
        n = int(experts.numel())
        pieces = list(experts.split(max(_SELECTIVE_GATHER_MIN, -(-n // _SELECTIVE_GATHER_PIECES))))

    def take(t, piece):
        return t[piece] if isinstance(piece, slice) else t.index_select(0, piece)

    out = None
    if len(pieces) > 1:
        out = torch.empty((n,) + inner, dtype = qs.dtype, device = packed_all.device)
    row = 0
    for piece in pieces:
        packed = take(packed_all, piece)
        k = packed.shape[0]
        dest = out[row : row + k] if out is not None else None
        state2 = None
        if absmax2_all is not None:
            state2 = QuantState(
                absmax = take(absmax2_all, piece).reshape(-1), code = qs.state2.code,
                blocksize = qs.state2.blocksize, quant_type = qs.state2.quant_type, dtype = qs.state2.dtype,
            )
        piece_shape = (k,) + inner
        sub = QuantState(
            absmax = take(absmax_all, piece).reshape(-1), shape = torch.Size(piece_shape), code = qs.code,
            blocksize = qs.blocksize, quant_type = qs.quant_type, dtype = qs.dtype, offset = offset, state2 = state2,
        )
        weight = None
        try:
            from unsloth_zoo.temporary_patches.moe_triton_kernels import nf4_dequant_triton
            weight = nf4_dequant_triton(packed, sub, piece_shape, out = dest)
        except ImportError:
            pass
        if weight is None:
            sub_param = torch.Tensor._make_subclass(Params4bit, packed.reshape(-1, 1))
            sub_param.quant_state = sub
            sub_param._original_shape = torch.Size(piece_shape)
            slicer = _get_dequantize_4bit_in_slices()
            weight = slicer(sub_param) if slicer is not None else None
            if weight is None:
                weight = bnb.functional.dequantize_4bit(packed.reshape(-1, 1), sub)
        del packed, sub, state2
        if dest is None:
            out = weight.reshape(piece_shape)
        elif weight.data_ptr() != dest.data_ptr():
            dest.copy_(weight.reshape(piece_shape))
        row += k
        del weight, dest
    if not torch.compiler.is_compiling():   # a traced global write re-traces every call
        SELECTIVE_DEQUANT_STATS["dequant_calls"] += 1
        SELECTIVE_DEQUANT_STATS["experts_dequantized"] += n
        SELECTIVE_DEQUANT_STATS["experts_total"] += E
    return out.to(target_dtype) if target_dtype is not None else out


def _selective_dequant_plan(sources, num_tokens_per_expert, num_rows, experts_module = None, checkpoint_call = None):
    """Expert chunks to dequantize, or None to keep the full-stack path when off, traced, capturing, a source that cannot split exactly, or nothing to save."""
    mode = os.environ.get("UNSLOTH_MOE_SELECTIVE_DEQUANT", "auto")
    selective = mode == "1"
    chunk = _selective_dequant_chunk_experts()
    capped_scratch = False
    if (
        chunk == 0 and mode != "0" and experts_module is not None
        and _auto_dequant_cap_source(experts_module) != (None, None)   # flag / env first: unflagged models stop here
        and not torch.compiler.is_compiling()
        and not _cuda_capturing(num_tokens_per_expert.device)
    ):
        splits = [_bnb4bit_expert_split(source) for source in sources]
        E = int(num_tokens_per_expert.numel())
        if splits and all(split is not None and split[0] == E for split in splits):
            param = sources[0]
            while hasattr(param, "base_layer"):
                param = param.base_layer
            # The unchunked plan reads num_rows experts when the sync-free capped plan applies, else the whole stack.
            capped = not selective and 0 < num_rows and 8 * num_rows <= 7 * E
            chunk = _auto_dequant_chunk_experts(
                splits, param.quant_state.dtype, experts_module, num_tokens_per_expert.device,
                experts_needed = num_rows if capped else E, checkpoint_call = checkpoint_call,
            )
            # The chunked plan reads the routed counts on the host anyway: read only the routed experts.
            capped_scratch = chunk > 0
    if not selective and chunk == 0:
        if mode == "0":
            return None
        return _capped_dequant_plan(sources, num_tokens_per_expert, num_rows)
    if torch.compiler.is_compiling():
        return None
    device = num_tokens_per_expert.device
    if _cuda_capturing(device):
        return None
    E = int(num_tokens_per_expert.numel())
    for source in sources:
        split = _bnb4bit_expert_split(source)
        if split is None or split[0] != E:
            return None
    counts = num_tokens_per_expert.tolist()
    experts = [e for e, c in enumerate(counts) if c > 0] if (selective or capped_scratch) else list(range(E))
    if not experts:
        return None
    if not chunk and 8 * len(experts) > 7 * E:
        return None   # under 1/8 of the stack to save, not worth the gathers
    chunk = chunk or len(experts)
    ends = []
    total = 0
    for c in counts:
        total += c
        ends.append(total)
    chunks = []
    for i in range(0, len(experts), chunk):
        ids = experts[i : i + chunk]
        row_lo = ends[ids[0]] - counts[ids[0]]
        row_hi = ends[ids[-1]]
        if row_hi == row_lo:
            continue   # chunked without selective: no token routed to any of these experts
        contiguous = ids[-1] - ids[0] + 1 == len(ids)
        chunks.append((
            slice(ids[0], ids[-1] + 1) if contiguous else torch.tensor(ids, dtype = torch.int64, device = device),
            row_lo,
            row_hi,
            torch.tensor([ends[e] - row_lo for e in ids], dtype = torch.int32, device = device),
        ))
    if not chunks:
        return None
    SELECTIVE_DEQUANT_STATS["plans"] += 1
    return _SelectiveDequantPlan(E, num_rows, chunks)


def _capped_dequant_plan(sources, num_tokens_per_expert, num_rows):
    """Sync-free plan from shapes only: num_rows experts, routed ids ascending, then unrouted padding."""
    E = int(num_tokens_per_expert.numel())
    if num_rows <= 0 or 8 * num_rows > 7 * E:
        return None
    for source in sources:
        split = _bnb4bit_expert_split(source)
        if split is None or split[0] != E:
            return None
    counts = num_tokens_per_expert
    unrouted_last = (counts == 0).to(torch.int64) * E + torch.arange(E, device = counts.device)
    experts = torch.argsort(unrouted_last)[:num_rows]
    offsets = torch.cumsum(counts.index_select(0, experts), dim = 0, dtype = torch.int32)
    if not torch.compiler.is_compiling():
        SELECTIVE_DEQUANT_STATS["plans"] += 1
    return _SelectiveDequantPlan(E, num_rows, [(experts, 0, num_rows, offsets)])


def _slice_takes_triton(inputs, weight, plan):
    E, K, N = weight.shape
    if not (
        _GROUPED_MM_TRITON_OP is not None
        and inputs.device.type == "cuda"
        and inputs.dtype in (torch.bfloat16, torch.float16)
        and weight.dtype == inputs.dtype
        and _triton_grouped_mm_rows_ok(inputs.device, plan.num_rows, plan.num_experts, K, N)
    ):
        return False
    from unsloth_zoo.temporary_patches import moe_grouped_fp16 as mg
    return mg.triton_grouped_available(inputs.device)


def _grouped_mm_slice(inputs, weight, offsets, plan):
    """Grouped matmul for a slice of a planned problem; the Triton choice and tiles follow the whole (rows, experts) problem so each slice's result matches it."""
    if _slice_takes_triton(inputs, weight, plan):
        from unsloth_zoo.temporary_patches import moe_grouped_fp16 as mg
        return mg.generic_grouped_mm(
            inputs.contiguous(), weight, offsets, config_rows = (plan.num_rows, plan.num_experts),
        )
    return _grouped_mm_eager(inputs, weight, offsets)


def _slice_reads_views(inputs, weight, plan):
    # Views match the copy's bits only on Triton and the sm90/sm100 grouped GEMMs (behind the view probe); a per-expert
    # cuBLAS loop differs since a transposed operand takes another kernel (T4 fp16 K 5760: 3x max error).
    if _slice_takes_triton(inputs, weight, plan):
        return True
    device = inputs.device
    if device.type != "cuda" or is_rocm_torch(torch):
        return False
    index = device.index if device.index is not None else torch.cuda.current_device()
    return _triton_grouped_mm_capability(index)[0] in (9, 10) and _grouped_mm_supported_on(device)


def _transposed_for_slice(weight, inputs, plan):
    weight = weight.transpose(-2, -1)
    return weight if _slice_reads_views(inputs, weight, plan) else weight.contiguous()


def _selective_grouped_mm(inputs, weight_provider, plan, transpose):
    if len(plan.chunks) == 1:
        experts, _, _, offsets = plan.chunks[0]
        weight = weight_provider(experts)
        if transpose:
            weight = _transposed_for_slice(weight, inputs, plan)
        return _grouped_mm_slice(inputs, weight, offsets, plan)
    out = None
    for experts, row_lo, row_hi, offsets in plan.chunks:
        weight = weight_provider(experts)
        if transpose:
            weight = _transposed_for_slice(weight, inputs, plan)
        rows = inputs[row_lo : row_hi]
        if rows.data_ptr() % 16:
            rows = rows.clone()   # grouped GEMMs want 16-byte aligned operands
        part = _grouped_mm_slice(rows, weight, offsets, plan)
        del weight
        if out is None:
            out = inputs.new_empty((inputs.shape[0], part.shape[-1]))
        out[row_lo : row_hi] = part
        del part
    return out


class _GroupedMMSelectiveRecompute(torch.autograd.Function):
    """_GroupedMMRecompute over a _SelectiveDequantPlan: forward and dX read only the planned experts."""

    @staticmethod
    def forward(ctx, inputs, weight_provider, plan):
        ctx.weight_provider = weight_provider
        ctx.plan = plan
        with torch.no_grad():
            return _selective_grouped_mm(inputs, weight_provider, plan, False)

    @staticmethod
    def backward(ctx, grad_output):
        with torch.no_grad():
            grad_input = _selective_grouped_mm(grad_output.contiguous(), ctx.weight_provider, ctx.plan, True)
        return grad_input, None, None


def _mxfp4_expert_layout(source, proj_type, hidden_dim, model_type, experts_module):
    """(packed param, transpose_b: weight is P^T of the packed rows) for a frozen packed MXFP4 stack, else None."""
    param = source
    while hasattr(param, "base_layer"):
        param = param.base_layer
    if not is_packed_expert_param(param) or param.requires_grad:
        return None
    transposed = packed_param_transposed(param)
    cache = experts_module.__dict__.setdefault("_unsloth_mxfp4_layout", {})
    key = (proj_type, hidden_dim, model_type, transposed, tuple(param._original_shape), type(param).__name__)
    if key not in cache:
        # preprocess_weight on a meta stand-in: identity or a transpose view, anything else is unsupported.
        meta = torch.empty(tuple(param._original_shape), device = "meta")
        try:
            weight = preprocess_weight(meta, proj_type, hidden_dim, model_type, experts_module = experts_module)
        except Exception:
            weight = None
        flipped = meta.transpose(-2, -1)
        if weight is meta or (weight is not None and weight.shape == meta.shape and weight.stride() == meta.stride()):
            cache[key] = transposed
        elif weight is not None and weight.shape == flipped.shape and weight.stride() == flipped.stride():
            cache[key] = not transposed
        else:
            cache[key] = None
    transpose_b = cache[key]
    return None if transpose_b is None else (param, transpose_b)


def _mxfp4_fused_enabled(param, dtype, rows = None) -> bool:
    """UNSLOTH_MXFP4_FUSED_GEMM: auto fuses below UNSLOTH_MXFP4_FUSED_MAX_ROWS (192) rows per expert (dequant plus
    cuBLAS wins above on B200); 1 always, dequant never, 0 never plus legacy decode path."""
    if dtype != torch.bfloat16 or param.device.type != "cuda":
        return False
    mode = os.environ.get("UNSLOTH_MXFP4_FUSED_GEMM", "auto")
    if mode in ("0", "dequant"):
        return False
    if mode != "1" and rows is not None:
        limit = int(os.environ.get("UNSLOTH_MXFP4_FUSED_MAX_ROWS", "192"))
        if rows >= limit * param.shape[0]:
            return False
    from unsloth_zoo.mxfp4_gemm import mxfp4_grouped_mm_available
    return mxfp4_grouped_mm_available(param.device)


def _mxfp4_base_grouped_mm(inputs, offsets, counts, weight_provider, recompute, layout):
    """Fused decode-in-GEMM, else dequantize with a transposed decode for backward."""
    param, transpose_b = layout
    if is_new_packed_expert_param(param):
        # NVFP4 / MXFP8: chunked dequantize + grouped GEMM for forward and dX (packed_experts.py).
        from unsloth_zoo.packed_experts import packed_expert_grouped_linear
        if (
            inputs.dtype == torch.float32 and inputs.device.type == "cuda"
            and torch.is_autocast_enabled("cuda") and torch.get_autocast_dtype("cuda") in (torch.bfloat16, torch.float16)
        ):
            inputs = inputs.to(torch.get_autocast_dtype("cuda"))
        return packed_expert_grouped_linear(inputs, param, counts, transpose_b)
    scales = param.mxfp4_scales
    if scales.device != param.device:
        scales = param.mxfp4_scales = scales.to(param.device)
    if (
        inputs.dtype == torch.float32 and inputs.device.type == "cuda"
        and torch.is_autocast_enabled("cuda") and torch.get_autocast_dtype("cuda") == torch.bfloat16
    ):
        inputs = inputs.to(torch.bfloat16)  # what autocast does to torch._grouped_mm's operands
    if _mxfp4_fused_enabled(param, inputs.dtype, inputs.shape[0]):
        from unsloth_zoo.mxfp4_gemm import mxfp4_expert_grouped_mm
        return mxfp4_expert_grouped_mm(inputs, param.data, scales, counts, transpose_b = transpose_b)
    if recompute and os.environ.get("UNSLOTH_MXFP4_FUSED_GEMM") != "0":
        weight_provider.transposed = lambda: param.dequantize(
            inputs.dtype, token_counts = counts, transpose = not transpose_b,
        )
    return _base_grouped_mm(inputs, offsets, weight_provider, recompute)


def _is_fp8_block_layout(layout) -> bool:
    return layout is not None and getattr(layout[0], "packed_format", None) == "fp8_block"


def _fp8_block_base_mm(inputs, offsets, counts, layout, lora, keep_slot, proj):
    """Block-FP8 experts on the W8A16 grouped GEMM (moe_fp8_grouped): (output, LoRA left for the separated path)."""
    from unsloth_zoo.temporary_patches.moe_fp8_grouped import fp8_block_base_and_lora
    param, transpose_b = layout
    if (
        inputs.dtype == torch.float32 and inputs.device.type == "cuda"
        and torch.is_autocast_enabled("cuda") and torch.get_autocast_dtype("cuda") == torch.bfloat16
    ):
        inputs = inputs.to(torch.bfloat16)
    return fp8_block_base_and_lora(inputs, param, counts, offsets, transpose_b, lora, keep_slot = keep_slot, proj = proj)


_GROUPED_GEMM_AVAILABLE = None
_TORCH_GROUPED_MM_AVAILABLE = hasattr(torch, "_grouped_mm")

# GPU support for torch._grouped_mm, verified via runtime probe.
_TORCH_GROUPED_MM_SUPPORTED = None


@torch.compiler.disable
def _run_probe_eagerly(probe):
    """Graph-break so lazy probes never run on FakeTensors, whose meta check can reject what the real
    kernel accepts and latch the cached flag False (torch 2.14 `_grouped_mm_fp16_cublaslt_supported` needs CUDA 13.3+)."""
    return probe()


def _grouped_mm_probe_device():
    # Typed device, not a bare index: an int resolves to the default accelerator, losing this branch.
    if torch.cuda.is_available():
        return torch.device("cuda", torch.cuda.current_device())
    if hasattr(torch, "xpu") and torch.xpu.is_available():
        return torch.device("xpu", torch.xpu.current_device())
    return None


def _grouped_mm_device_kind(backend, index):
    try:
        p = backend.get_device_properties(index)
        return (p.name, getattr(p, "major", None), getattr(p, "minor", None), getattr(p, "gcnArchName", None))
    except Exception:
        return index


_GROUPED_MM_FOREIGN = {}   # (type, index) -> None if same GPU model as the probe device, else its model
# (type, index) the process-wide flags were probed on; a later current-device switch must not move it.
_GROUPED_MM_HOME = None
_GROUPED_MM_HOME_LOCK = threading.Lock()
# Every visible accelerator is the home card's model: per-call gates read the process-wide flags.
_GROUPED_MM_HOMOGENEOUS = False


def _grouped_mm_home():
    """Card the process-wide flags describe; locked so concurrent first callers on different cards agree."""
    global _GROUPED_MM_HOME, _GROUPED_MM_HOMOGENEOUS
    if _GROUPED_MM_HOME is None:
        device = _grouped_mm_probe_device()
        anchored = False
        with _GROUPED_MM_HOME_LOCK:
            if _GROUPED_MM_HOME is None and device is not None and device.index is not None:
                _GROUPED_MM_HOME = (device.type, device.index)
                _GROUPED_MM_FOREIGN.setdefault(_GROUPED_MM_HOME, None)
                anchored = True
        # Classify other cards now (metadata only) so a traced first use on another card never reaches the
        # compiler-disabled resolver (graph break / fullgraph error).
        if anchored:
            try:
                count = getattr(torch, device.type).device_count()
            except Exception:
                count = 0
            for i in range(count):
                if (device.type, i) not in _GROUPED_MM_FOREIGN:
                    _resolve_grouped_mm_foreign_kind(torch.device(device.type, i), (device.type, i))
            _GROUPED_MM_HOMOGENEOUS = _grouped_mm_all_cards_alike(device.type, count)
    return torch.device(*_GROUPED_MM_HOME) if _GROUPED_MM_HOME is not None else _grouped_mm_probe_device()


def _grouped_mm_all_cards_alike(home_type, count):
    """Every visible card of the home's type is its model, and no other accelerator type has cards."""
    if count < 1 or any(_GROUPED_MM_FOREIGN.get((home_type, i), 0) is not None for i in range(count)):
        return False
    other = "xpu" if home_type == "cuda" else "cuda"
    try:
        backend = getattr(torch, other, None)
        return not (backend is not None and backend.is_available() and backend.device_count() > 0)
    except Exception:
        return False


def _grouped_mm_traced_kind(device):
    # Trace-time lookup, never resolves: None = the home model (or not a GPU), False = never seen eagerly.
    if device is None or device.type not in ("cuda", "xpu") or device.index is None: return None
    return _GROUPED_MM_FOREIGN.get((device.type, device.index), False)


def _grouped_mm_foreign_kind(device):
    if device is None or device.type not in ("cuda", "xpu") or device.index is None: return None
    key = (device.type, device.index)
    if key in _GROUPED_MM_FOREIGN: return _GROUPED_MM_FOREIGN[key]
    return _run_probe_eagerly(lambda: _resolve_grouped_mm_foreign_kind(device, key))


def _resolve_grouped_mm_foreign_kind(device, key):
    home = _grouped_mm_home()
    kind = None
    if home is not None and (home.type, home.index) != (device.type, device.index):
        # Typed: a CUDA home must not answer for an XPU card (or the reverse) on a host with both.
        kind = (device.type, _grouped_mm_device_kind(getattr(torch, device.type), device.index))
        if home.type == device.type and kind == (home.type, _grouped_mm_device_kind(getattr(torch, home.type), home.index)):
            kind = None
    _GROUPED_MM_FOREIGN[key] = kind
    return kind


# Per GPU model other than the home card's.
_TORCH_GROUPED_MM_SUPPORTED_BY_KIND = {}


def _check_torch_grouped_mm_supported(device = None):
    """Check torch._grouped_mm support on `device` (default: current); a runtime probe is the only reliable check."""
    global _TORCH_GROUPED_MM_SUPPORTED
    if device is not None:
        kind = _grouped_mm_foreign_kind(device)
        if kind is not None:
            supported = _TORCH_GROUPED_MM_SUPPORTED_BY_KIND.get(kind)
            if supported is not None: return supported
            if not _TORCH_GROUPED_MM_AVAILABLE: return False
            return _run_probe_eagerly(lambda: _probe_torch_grouped_mm_supported(device))
    if _TORCH_GROUPED_MM_SUPPORTED is not None: return _TORCH_GROUPED_MM_SUPPORTED
    # Definitive negatives stay traceable so fullgraph traces don't break.
    if not _TORCH_GROUPED_MM_AVAILABLE or _grouped_mm_probe_device() is None:
        _TORCH_GROUPED_MM_SUPPORTED = False
        return False
    return _run_probe_eagerly(_probe_torch_grouped_mm_supported)


def _torch_version_tuple():
    try:
        return tuple(int(x) for x in torch.__version__.split("+")[0].split(".")[:2])
    except Exception:
        return (0, 0)


# CUDA not ROCm: torch 2.8 hard-raises unless dprops->major == 9 (Blas.cpp sm90_only); 2.9+ sends other archs to
# _grouped_mm_fallback instead of raising (GroupedBlas.cpp, _grouped_mm_cuda).
_TORCH_IS_CUDA_BUILD = not is_rocm_torch(torch)
_TORCH_GROUPED_MM_SM90_ONLY = _TORCH_IS_CUDA_BUILD and _torch_version_tuple() == (2, 8)
_TORCH_GROUPED_MM_FALLS_BACK = _TORCH_IS_CUDA_BUILD and _torch_version_tuple() >= (2, 9)


def _grouped_mm_falls_back_internally(device_type, kind):
    """torch serves grouped_mm on unprobed cards on CUDA 2.9+ (natively or via its fallback), and on 2.8 only on sm90;
    ROCm (some cards crash, unsloth#12391) and XPU make no such promise."""
    if device_type != "cuda": return False
    if _TORCH_GROUPED_MM_FALLS_BACK: return True
    info = kind[1] if isinstance(kind, tuple) and len(kind) == 2 else None
    return _TORCH_GROUPED_MM_SM90_ONLY and isinstance(info, tuple) and info[1] == 9


def _grouped_mm_supported_on(device):
    # Absent symbol (torch 2.6/2.7): the traceable definitive negative, no classification.
    if _GROUPED_MM_HOMOGENEOUS or not _TORCH_GROUPED_MM_AVAILABLE:
        return _check_torch_grouped_mm_supported()
    if torch.compiler.is_compiling():
        return _grouped_mm_supported_while_tracing(device)
    kind = _grouped_mm_foreign_kind(device)
    if kind is None:
        return _check_torch_grouped_mm_supported()
    return _check_torch_grouped_mm_supported(device)


def _grouped_mm_supported_while_tracing(device):
    # Never probes while tracing (graph break or fullgraph error); an unwarmed card takes the home answer only where
    # torch falls back internally, else the manual loop, which is safe but breaks a fullgraph trace.
    home = _check_torch_grouped_mm_supported()
    kind = _grouped_mm_traced_kind(device)
    if kind is None or _GROUPED_MM_HOMOGENEOUS: return home
    known = None if kind is False else _TORCH_GROUPED_MM_SUPPORTED_BY_KIND.get(kind)
    if known is not None: return known
    return home and _grouped_mm_falls_back_internally(device.type, kind)


# Some ROCm GPUs segfault in grouped_mm instead of raising (unsloth#12391): run the kernels in a throwaway interpreter first.
_GROUPED_MM_CRASH_PROBE = r"""
import sys
if sys.platform == "win32":   # no "python.exe has stopped working" dialog when the kernel faults
    import ctypes; ctypes.windll.kernel32.SetErrorMode(0x0003)
import torch
d = torch.device("cuda", int(sys.argv[1]))
def probe(x, w, offs):
    offs = torch.tensor(offs, device = d, dtype = torch.int32)
    try: torch._grouped_mm(x, w, offs = offs); torch.cuda.synchronize(d)
    except Exception: pass   # a Python error is caught in-process too; only a crash or hang matters here
half = dict(device = d, dtype = torch.float16)
bf16 = dict(device = d, dtype = torch.bfloat16)
w_t  = torch.ones(4, 64, 32, **bf16).transpose(-2, -1)
probe(torch.ones(1, 8, **half), torch.ones(1, 8, 8, **half), [1])
probe(torch.ones(32, 32, **bf16), w_t, [8, 16, 24, 32])
probe(torch.ones(32, 32, **bf16), w_t.contiguous(), [8, 16, 24, 32])
# The in-process training probe's backward (dX and the 2D x 2D dW) runs here first too.
try:
    x = torch.ones(32, 32, **bf16).requires_grad_(); w = torch.ones(4, 32, 48, **bf16).requires_grad_()
    offs = torch.tensor([8, 8, 13, 32], device = d, dtype = torch.int32)
    torch._grouped_mm(x, w, offs = offs).backward(torch.ones(32, 48, **bf16)); torch.cuda.synchronize(d)
except Exception: pass
"""
_GROUPED_MM_SURVIVES = None
_GROUPED_MM_SURVIVES_BY_KIND = {}
_GROUPED_MM_SURVIVES_LOCK = threading.Lock()


def _grouped_mm_survives_out_of_process(device):
    global _GROUPED_MM_SURVIVES
    kind = _grouped_mm_foreign_kind(device)
    if kind is not None:
        with _GROUPED_MM_SURVIVES_LOCK:
            if kind not in _GROUPED_MM_SURVIVES_BY_KIND:
                _GROUPED_MM_SURVIVES_BY_KIND[kind] = _run_grouped_mm_crash_probe(device)
        return _GROUPED_MM_SURVIVES_BY_KIND[kind]
    if _GROUPED_MM_SURVIVES is not None: return _GROUPED_MM_SURVIVES
    # Publish once known: concurrent first callers wait for the child, never run the kernel.
    with _GROUPED_MM_SURVIVES_LOCK:
        if _GROUPED_MM_SURVIVES is None: _GROUPED_MM_SURVIVES = _run_grouped_mm_crash_probe(device)
    return _GROUPED_MM_SURVIVES


def _run_grouped_mm_crash_probe(device):
    # AMD only: CUDA and XPU keep the in-process probe.
    if not is_rocm_torch(torch) or device.type != "cuda": return True
    # Studio's Python _grouped_mm fallback (gfx120X) is active: this process never runs the native kernel.
    try:
        dump = torch._C._dispatch_dump("aten::_grouped_mm").splitlines()
        if any(l.startswith("CUDA:") and ".cpp:" not in l for l in dump): return True
    except Exception:
        pass
    import subprocess
    index, env = device.index, None
    # ROCr / ordinal selectors compose with the HIP mask unmirrorably: keep the parent's env and index.
    layered = any((os.environ.get(var) or "").strip() for var in ("ROCR_VISIBLE_DEVICES", "GPU_DEVICE_ORDINAL"))
    if torch.cuda.device_count() > 1 and not layered:
        # Child sees only this card; HIP indexes into the inherited mask.
        mask = os.environ.get("HIP_VISIBLE_DEVICES") or os.environ.get("CUDA_VISIBLE_DEVICES")
        mask = (mask or "").strip()
        if len(mask) >= 2 and mask[0] == mask[-1] == '"': mask = mask[1:-1]
        # clr keeps the first of a repeated entry.
        mask = list(dict.fromkeys(m.strip() for m in mask.split(","))) if mask else None
        # Only plain ordinals map token -> logical index (UUIDs alias them); PAL (Windows) enumerates in physical order.
        plain = mask is None or (
            all(m.isdigit() for m in mask) and (sys.platform != "win32" or mask == sorted(mask, key = int))
        )
        if plain and (mask is None or index < len(mask)):
            visible = mask[index] if mask else str(index)
            index, env = 0, dict(os.environ, HIP_VISIBLE_DEVICES = visible, CUDA_VISIBLE_DEVICES = visible)
    # Not multiprocessing: spawn re-imports the caller's __main__.
    try:
        result = subprocess.run(
            [sys.executable, "-c", _GROUPED_MM_CRASH_PROBE, str(index)], env = env,
            stdout = subprocess.DEVNULL, stderr = subprocess.DEVNULL, timeout = 180,
            creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0),
        ).returncode
    except Exception as e:
        result = type(e).__name__
    if result == 0: return True
    _log_info(f"Unsloth: torch._grouped_mm probe crashed on ROCm GPU {device.index} ({result}); disabling grouped_mm.")
    return False


def _grouped_mm_runs_on(device):
    _GROUPED_MM_LAST_REFUSAL[0] = None
    try:
        # Dummy call verifies real support (symbol may exist but hardware unsupported, e.g. < H100).
        dtype = torch.float16

        # 1 expert, 1 token, dim 8 (safe alignment).
        x = torch.ones((1, 8), device=device, dtype=dtype)
        w = torch.ones((1, 8, 8), device=device, dtype=dtype)
        offs = torch.tensor([1], device=device, dtype=torch.int32)

        torch._grouped_mm(x, w, offs=offs)
        del x, w, offs
    except Exception:
        return False
    _GROUPED_MM_LAST_REFUSAL[0] = _grouped_mm_trains_on(device)
    return _GROUPED_MM_LAST_REFUSAL[0] is None


_GROUPED_MM_PROBE_COUNTS = (8, 0, 5, 19)
_GROUPED_MM_TRAINING_PROBE_FAILURE = None
_GROUPED_MM_LAST_REFUSAL = [None]


def _grouped_mm_probe_dtype(device):
    if device.type == "cuda" and not is_rocm_torch(torch):
        try:
            if torch.cuda.get_device_capability(device)[0] < 8: return torch.float16
        except Exception:
            return torch.float16
    return torch.bfloat16


def _grouped_mm_on_device(device):
    # torch picks the kernel from the current device, not the operands'.
    backend = getattr(torch, device.type, None) if device.type in ("cuda", "xpu") else None
    context = getattr(backend, "device", None)
    return context(device) if context is not None else contextlib.nullcontext()


def _grouped_mm_trains_on(device):
    """Training-shaped fwd + dX + dW vs per-expert matmuls; None when it runs, else why not. Windows CUDA wheels serve
    one fp16 expert but refuse bf16 multi-expert. Integer operands: a wrong result misses by 1 or more. OOM is no verdict."""
    if os.environ.get("UNSLOTH_MOE_GROUPED_MM_PROBE", "1") == "0": return None
    dtype = _grouped_mm_probe_dtype(device)
    counts = _GROUPED_MM_PROBE_COUNTS
    try:
        with _grouped_mm_on_device(device), torch.inference_mode(False), torch.enable_grad():
            # CPU generator: the global RNG stays untouched.
            gen = torch.Generator(device = "cpu").manual_seed(0)
            E, M, K, N = len(counts), sum(counts), 32, 48
            # device = "cpu": a torch.set_default_device("cuda") app must not move the reference off the generator.
            x, w, dy = (torch.randint(-2, 3, shape, generator = gen, device = "cpu").double()
                        for shape in ((M, K), (E, K, N), (M, N)))
            ends = torch.tensor(counts, device = "cpu").cumsum(0).tolist()
            x_d = x.to(device = device, dtype = dtype).requires_grad_()
            w_d = w.to(device = device, dtype = dtype).requires_grad_()
            offs = torch.tensor(ends, device = device, dtype = torch.int32)
            y = torch._grouped_mm(x_d, w_d, offs = offs)
            dx, dw = torch.autograd.grad(y, (x_d, w_d), dy.to(device = device, dtype = dtype))
            spans = list(zip([0] + ends[:-1], ends))
            want = (
                ("forward", y, torch.cat([x[s:e] @ w[g] for g, (s, e) in enumerate(spans)])),
                ("dX", dx, torch.cat([dy[s:e] @ w[g].T for g, (s, e) in enumerate(spans)])),
                ("dW", dw, torch.stack([x[s:e].T @ dy[s:e] for s, e in spans])),
            )
            for name, got, ref in want:
                # The exact answers are small integers (at most 192, exact in bf16 / fp16), so a wrong kernel misses
                # by 1 or more. A correct one can still carry fp32 accumulation residue: gfx1151's grouped_mm gives
                # 2**-19 where the answer is 0. Half a unit tells the two apart; `not <=` also rejects a NaN.
                if got.shape != ref.shape or not float((got.detach().double().cpu() - ref).abs().max()) <= 0.5:
                    raise RuntimeError(f"{name} differs from per-expert matmuls")
        return None
    except torch.OutOfMemoryError:
        return None
    except Exception as exc:
        reason = f"{str(dtype).replace('torch.', '')}, {len(counts)} experts: {type(exc).__name__}: {exc}"
        return reason.splitlines()[0][:240]


def _probe_torch_grouped_mm_supported(device = None):
    global _TORCH_GROUPED_MM_SUPPORTED, _TRANSPOSED_VIEW_GROUPED_MM_SAFE, _GROUPED_MM_TRAINING_PROBE_FAILURE
    kind = _grouped_mm_foreign_kind(device)
    if kind is not None:
        supported = _TORCH_GROUPED_MM_SUPPORTED_BY_KIND.get(kind)
        if supported is None:
            supported = _TORCH_GROUPED_MM_AVAILABLE and _grouped_mm_survives_out_of_process(device) and _grouped_mm_runs_on(device)
            _TORCH_GROUPED_MM_SUPPORTED_BY_KIND[kind] = supported
            # Same eager region: a traced first use of this model must not break again on the view check.
            if kind not in _TRANSPOSED_VIEW_SAFE_BY_KIND:
                _TRANSPOSED_VIEW_SAFE_BY_KIND[kind] = supported and _transposed_view_probe(device)
        return supported
    if _TORCH_GROUPED_MM_SUPPORTED is not None: return _TORCH_GROUPED_MM_SUPPORTED

    # The anchored card, not whichever is current now: the flags must describe one card.
    device = _grouped_mm_home() if _TORCH_GROUPED_MM_AVAILABLE else None
    _GROUPED_MM_LAST_REFUSAL[0] = None
    if device is None or not _grouped_mm_survives_out_of_process(device):
        _TORCH_GROUPED_MM_SUPPORTED = False
    else:
        _TORCH_GROUPED_MM_SUPPORTED = _grouped_mm_runs_on(device)
    _GROUPED_MM_TRAINING_PROBE_FAILURE = _GROUPED_MM_LAST_REFUSAL[0]
    # Answer the view check here so a cold compiled block does not graph-break on it.
    if _TRANSPOSED_VIEW_GROUPED_MM_SAFE is None:
        _TRANSPOSED_VIEW_GROUPED_MM_SAFE = _TORCH_GROUPED_MM_SUPPORTED and _transposed_view_probe(device)
    return _TORCH_GROUPED_MM_SUPPORTED


def _warm_grouped_mm_devices(devices):
    """On mixed-GPU hosts only, probe eagerly one card per GPU model among the devices this process uses, so a later
    trace reads its own answers; never foreign cards (torchrun ranks would pile CUDA contexts onto one card)."""
    if _GROUPED_MM_HOMOGENEOUS or torch.compiler.is_compiling(): return
    seen = set()
    for device in devices:
        try:
            if device is None or device.type not in ("cuda", "xpu") or device.index is None: continue
            kind = _grouped_mm_foreign_kind(device)
            if kind is None or kind in seen: continue
            seen.add(kind)
            _check_torch_grouped_mm_supported(device)
        except Exception:
            pass


# One-time check that torch._grouped_mm on a transposed bf16 view matches the contiguous copy; insurance only, since
# pytorch/pytorch issue 186365 was a usage error (offs must be cumulative group ends) and no view miscompute is known.
_TRANSPOSED_VIEW_GROUPED_MM_SAFE = None


def _transposed_view_grouped_mm_is_safe():
    global _TRANSPOSED_VIEW_GROUPED_MM_SAFE
    if _TRANSPOSED_VIEW_GROUPED_MM_SAFE is not None:
        return _TRANSPOSED_VIEW_GROUPED_MM_SAFE
    if not _TORCH_GROUPED_MM_AVAILABLE or _grouped_mm_probe_device() is None:
        _TRANSPOSED_VIEW_GROUPED_MM_SAFE = False
        return False
    return _run_probe_eagerly(_probe_transposed_view_grouped_mm_is_safe)


_TRANSPOSED_VIEW_SAFE_BY_KIND = {}


def _transposed_view_safe_on(device):
    """View probe on `device`'s GPU model; the home model keeps the process-wide flag."""
    if _GROUPED_MM_HOMOGENEOUS or not _TORCH_GROUPED_MM_AVAILABLE: return _transposed_view_grouped_mm_is_safe()
    if torch.compiler.is_compiling():
        kind = _grouped_mm_traced_kind(device)
        if kind is None: return _transposed_view_grouped_mm_is_safe()
        # Unprobed card: the contiguous copy (correct, traceable), never the home card's verdict.
        return False if kind is False else bool(_TRANSPOSED_VIEW_SAFE_BY_KIND.get(kind, False))
    kind = _grouped_mm_foreign_kind(device)
    if kind is None: return _transposed_view_grouped_mm_is_safe()
    safe = _TRANSPOSED_VIEW_SAFE_BY_KIND.get(kind)
    if safe is not None: return safe
    return _run_probe_eagerly(lambda: _probe_transposed_view_grouped_mm_is_safe(device))


def _probe_transposed_view_grouped_mm_is_safe(device = None):
    global _TRANSPOSED_VIEW_GROUPED_MM_SAFE
    kind = _grouped_mm_foreign_kind(device)
    if kind is not None:
        if kind not in _TRANSPOSED_VIEW_SAFE_BY_KIND:
            _TRANSPOSED_VIEW_SAFE_BY_KIND[kind] = _transposed_view_probe(device)
        return _TRANSPOSED_VIEW_SAFE_BY_KIND[kind]
    if _TRANSPOSED_VIEW_GROUPED_MM_SAFE is not None:
        return _TRANSPOSED_VIEW_GROUPED_MM_SAFE
    _TRANSPOSED_VIEW_GROUPED_MM_SAFE = _transposed_view_probe(_grouped_mm_home())
    return _TRANSPOSED_VIEW_GROUPED_MM_SAFE


def _transposed_view_probe(device):
    safe = False
    try:
        if _TORCH_GROUPED_MM_AVAILABLE and device is not None and _grouped_mm_survives_out_of_process(device):
            E, N, K, M = 4, 64, 32, 32
            # local generator: never touch the process-wide RNG (manual_seed would shift training)
            gen = torch.Generator(device=device).manual_seed(0)
            A = torch.randn(M, K, dtype=torch.bfloat16, device=device, generator=gen)
            w = torch.randn(E, N, K, dtype=torch.bfloat16, device=device, generator=gen)
            w_t = w.transpose(-2, -1)
            w_tc = w_t.contiguous()
            per = M // E
            offs = torch.arange(per, M + 1, per, dtype=torch.int32, device=device)[:E]
            offs[-1] = M
            ok, ref = True, None
            for _ in range(6):
                row_wise_max = A.abs().amax(dim=-1, keepdim=True)
                _ = A / (row_wise_max / 448.0)     # allocator churn from the #186365 report
                r_view = torch._grouped_mm(A, w_t, offs=offs)
                r_contig = torch._grouped_mm(A, w_tc, offs=offs)
                if (r_view - r_contig).abs().max().item() > 1e-2:   # view disagrees with contiguous
                    ok = False; break
                if ref is None:
                    ref = r_view
                elif (r_view - ref).abs().max().item() > 1e-2:      # view not stable across calls
                    ok = False; break
            safe = ok
    except Exception:
        safe = False   # anything unexpected -> keep the safe contiguous copy
    return safe


_TRITON_ALLOCATOR_INITIALIZED = False
_PERSISTENT_BUFFER = {}   # per device index: a card must never be handed another card's scratch
_original_peft_get_peft_model = None


def _init_triton_allocator():
    """Initialize a persistent Triton allocator to avoid per-call allocation overhead."""
    global _TRITON_ALLOCATOR_INITIALIZED
    if _TRITON_ALLOCATOR_INITIALIZED: return

    try:
        import triton

        # Persistent buffer that grows as needed, avoiding per-kernel allocations.
        def persistent_alloc_fn(size: int, alignment: int, stream):
            # Triton launches on, and asks for scratch on, the current device.
            device = torch.cuda.current_device()
            buffer = _PERSISTENT_BUFFER.get(device)
            # Round up to nearest 128 bytes for alignment / fewer reallocations.
            rounded_size = ((size + 128 - 1) // 128) * 128

            if (
                buffer is None
                or buffer.numel() * buffer.element_size()
                < rounded_size
            ):
                # 10% headroom; uint8 for raw byte storage.
                buffer = _PERSISTENT_BUFFER[device] = torch.empty(
                    int(rounded_size * 1.1), device=torch.device("cuda", device), dtype=torch.uint8
                )
                buffer.__hibernate__ = {"type": "ignore"}
            return buffer

        triton.set_allocator(persistent_alloc_fn)
        triton._unsloth_allocator_set = True
        _TRITON_ALLOCATOR_INITIALIZED = True
    except Exception:
        pass


def _check_grouped_gemm_available():
    """Check if Unsloth grouped GEMM kernels are available."""
    if os.environ.get("UNSLOTH_DISABLE_MOE_TRITON", "0") == "1": return False
    if is_mlx_available(): return False

    global _GROUPED_GEMM_AVAILABLE
    if _GROUPED_GEMM_AVAILABLE is not None: return _GROUPED_GEMM_AVAILABLE

    # The kernel asserts `X.device.type == "cuda"` on entry, so importable is not the
    # same as usable: on a CPU box with unsloth installed this used to answer yes,
    # select_moe_backend picked "unsloth_triton", and the first expert forward died on
    # "X and W must be on CUDA" instead of taking the native loop. Asked here rather
    # than at the call site, the way _check_torch_grouped_mm_supported already refuses
    # without an accelerator.
    if not torch.cuda.is_available():
        _GROUPED_GEMM_AVAILABLE = False
        return False

    # Triton 3.3 (torch 2.7) lacks tl.make_tensor_descriptor, which the JIT resolves while hashing: use the native loop.
    try:
        import triton.language as tl
        if not hasattr(tl, "make_tensor_descriptor"):
            _GROUPED_GEMM_AVAILABLE = False
            return False
    except Exception:
        _GROUPED_GEMM_AVAILABLE = False
        return False

    try:
        from unsloth.kernels.moe.grouped_gemm.interface import grouped_gemm, supports_tma
        _GROUPED_GEMM_AVAILABLE = True
        _init_triton_allocator()
    except (ImportError, ModuleNotFoundError):
        # A temporary patch asking while unsloth itself imports: circular, not absent. Decide later.
        if _unsloth_importing():
            return False
        _GROUPED_GEMM_AVAILABLE = False
    return _GROUPED_GEMM_AVAILABLE


from functools import lru_cache, wraps


def _unsloth_importing():
    return bool(getattr(getattr(sys.modules.get("unsloth"), "__spec__", None), "_initializing", False))


_SELECTED_MOE_BACKEND = None


def select_moe_backend():
    """Selects the MoE backend from UNSLOTH_MOE_BACKEND and availability: grouped_mm, unsloth_triton or native_torch, defaulting to grouped_mm."""
    # This Unsloth Zoo code section is licensed under AGPL3
    global _SELECTED_MOE_BACKEND
