_GROUPED_MM_FALLBACK_LOGGED = set()


def _log_grouped_mm_fallback(reason, fallback):
    line = (
        f"Unsloth: torch._grouped_mm cannot run MoE training on this GPU ({reason}). Using {fallback} instead. "
        "Opt out: UNSLOTH_MOE_BACKEND=grouped_mm|unsloth_triton|native_torch picks the backend, "
        "UNSLOTH_MOE_GROUPED_TRITON=0 keeps Triton out of grouped_mm, UNSLOTH_MOE_GROUPED_MM_PROBE=0 skips this check."
    )
    # Shared with the compiled-cache copy of this module: one line per process.
    package = sys.modules.get("unsloth_zoo.temporary_patches.moe_utils")
    logged = getattr(package, "_GROUPED_MM_FALLBACK_LOGGED", _GROUPED_MM_FALLBACK_LOGGED)
    if line not in logged:
        logged.add(line)
        print(line)


def _use_grouped_mm_triton_standin(device, reason):
    global _GROUPED_MM_TRITON_STANDIN
    if device is None or not _grouped_mm_triton_standin_available(device):
        _log_grouped_mm_fallback(reason, "the per-expert loop for grouped_mm calls")
        return False
    _GROUPED_MM_TRITON_STANDIN = True
    _log_grouped_mm_fallback(reason, "MoE backend 'grouped_mm' on Unsloth's Triton grouped GEMM kernels")
    return True


def _select_grouped_mm_on_triton(explicit):
    """Auto takes the Triton stand-in only when the single-expert op works; older failures keep the old chain."""
    reason = _GROUPED_MM_TRAINING_PROBE_FAILURE
    if not explicit and reason is None:
        return False
    device = _grouped_mm_home() if _TORCH_GROUPED_MM_AVAILABLE else _grouped_mm_probe_device()
    if device is None or not _grouped_mm_triton_standin_available(device):
        return False
    if reason is None:
        reason = "the single-expert fp16 call failed" if _TORCH_GROUPED_MM_AVAILABLE else "this torch has no _grouped_mm"
    return _use_grouped_mm_triton_standin(device, reason)


def _select_moe_backend():
    requested = os.environ.get("UNSLOTH_MOE_BACKEND")
    if requested:
        if requested == "grouped_mm" and _check_torch_grouped_mm_supported():
            return "grouped_mm"
        if requested == "grouped_mm" and _select_grouped_mm_on_triton(explicit = True):
            return "grouped_mm"
        if requested == "unsloth_triton" and _check_grouped_gemm_available():
            return "unsloth_triton"
        if requested == "native_torch":
            return "native_torch"
        # Opt-in only; still needs torch._grouped_mm for LoRA GEMMs and fallbacks.
        if (
            requested == "sonic_moe"
            and _check_torch_grouped_mm_supported()
            and _check_sonic_moe_available()
        ):
            _log_info("Unsloth: Using MoE backend 'sonic_moe'")
            return "sonic_moe"
        _log_info(f"Unsloth: '{requested}' backend requested but is not available. Falling back to next available.")

    if _check_torch_grouped_mm_supported():
        _log_info("Unsloth: Using MoE backend 'grouped_mm'")
        return "grouped_mm"
    if _select_grouped_mm_on_triton(explicit = False):
        return "grouped_mm"
    backend = "native_torch"
    if _check_grouped_gemm_available() and _unsloth_triton_beats_loop():
        _log_info("Unsloth: Using MoE backend 'unsloth_triton'")
        backend = "unsloth_triton"
    if _GROUPED_MM_TRAINING_PROBE_FAILURE is not None:
        _log_grouped_mm_fallback(_GROUPED_MM_TRAINING_PROBE_FAILURE, f"MoE backend '{backend}'")
    return backend


def _unsloth_triton_beats_loop():
    """Below sm80 (T4 / V100) the Triton grouped GEMM ran 1.7x to 4x slower than the per-expert loop."""
    if is_rocm_torch(torch):
        return True
    try:
        return torch.cuda.get_device_capability()[0] >= 8
    except Exception:
        return True


def moe_compute_dtype(hidden_states):
    """W8A16 / W4A16 compute dtype: a half activation's own, else autocast's, else bf16 (or fp16). Never float32."""
    dtype = hidden_states.dtype
    if dtype in (torch.bfloat16, torch.float16):
        return dtype
    device_type = hidden_states.device.type
    try:
        if device_type != "meta" and torch.amp.is_autocast_available(device_type) and torch.is_autocast_enabled(device_type):
            autocast_dtype = torch.get_autocast_dtype(device_type)
            if autocast_dtype in (torch.bfloat16, torch.float16):
                return autocast_dtype
    except (AttributeError, RuntimeError, TypeError):
        pass
    # The activation's own device; is_bf16_supported() reads the current one and counts sm < 80 emulation.
    if (
        device_type == "cuda"
        and not is_rocm_torch(torch)
        and torch.cuda.get_device_capability(hidden_states.device)[0] < 8
    ):
        return torch.float16
    return torch.bfloat16


_SWAP_VIA_INSTANCE_DICT = _torch_version_tuple() < (2, 5)


def swap_moe_weights_for_call(experts_module, gate_up_proj, down_proj, forward_fn, *args):
    """Swaps dequantized weights into _parameters for one call and restores them (no __setattr__, so no (de)registration
    or hooks); used by the FP8 and bnb4bit MoE dispatchers."""
    # Swap only _parameters entries: a __dict__ write shadows later FSDP2 swaps (freed buffer); __dict__.pop, del and an
    # object() sentinel graph-break; dict setitem traces on every torch.
    names = ("gate_up_proj", "down_proj")
    params = experts_module._parameters
    instance_dict = experts_module.__dict__
    # torch < 2.5 Dynamo ignores the `_parameters` swap (wrong output, no grads): shadow via __dict__ instead.
    registered = {} if _SWAP_VIA_INSTANCE_DICT else {name: params[name] for name in names if name in params}
    saved = {name: instance_dict[name] for name in names if name not in registered and name in instance_dict}
    for name, tensor in zip(names, (gate_up_proj, down_proj)):
        if name in registered:
            params[name] = tensor
        else:
            object.__setattr__(experts_module, name, tensor)
    try:
        return forward_fn(experts_module, *args)
    finally:
        for name in names:
            if name in registered:
                params[name] = registered[name]
            elif name in saved:
                instance_dict[name] = saved[name]
            else:
                instance_dict.pop(name, None)


def _moe_uses_new_packed_expert_weights(module) -> bool:
    for name in ("gate_up_proj", "down_proj"):
        param = getattr(module, name, None)
        while param is not None and hasattr(param, "base_layer"):
            param = param.base_layer
        if is_new_packed_expert_param(param):
            return True
    return False


def forward_moe_backend(
    self,
    hidden_states: torch.Tensor,
    top_k_index: torch.Tensor,
    top_k_weights: torch.Tensor,
) -> torch.Tensor:
    """Dispatch MoE forward to the selected backend (keeps model-specific patches minimal)."""
    # This Unsloth Zoo code section is licensed under AGPL3

    # Absolute imports: this function is also copied into
    # unsloth_compiled_cache/moe_utils.py where relative imports of sibling
    # helpers don't resolve (only the dispatcher is copied).
    # Keep `except ImportError` around ONLY the import; runtime errors in the
    # bnb4bit/fp8 path must propagate, not fall through to a crashing backend.
    # Under Unsloth gradient checkpointing the backward replay takes the routing the first
    # (no-grad) pass used: the two passes run differently compiled graphs that can round a
    # router input across a top-k boundary.
    moe_checkpoint_routing = None
    try:
        from unsloth_zoo.gradient_checkpointing import moe_checkpoint_routing
    except ImportError:
        pass
    if moe_checkpoint_routing is not None:
        top_k_index, top_k_weights = moe_checkpoint_routing(self, top_k_index, top_k_weights)

    # Absolute import as above: the copy in the compiled module has no module globals.
    from unsloth_zoo.temporary_patches.moe_utils import _moe_uses_new_packed_expert_weights

    if _moe_uses_new_packed_expert_weights(self):
        # NVFP4 / MXFP8 stacks dequantize in chunks inside the grouped-GEMM forward; other backends index the weight.
        return forward_native_grouped_mm(self, hidden_states, top_k_index, top_k_weights)

    _moe_uses_bnb4bit_expert_weights = forward_moe_backend_bnb4bit = None
    try:
        from unsloth_zoo.temporary_patches.moe_utils_bnb4bit import (
            _moe_uses_bnb4bit_expert_weights,
            forward_moe_backend_bnb4bit,
        )
    except ImportError:
        pass
    if _moe_uses_bnb4bit_expert_weights is not None and _moe_uses_bnb4bit_expert_weights(self):
        result = forward_moe_backend_bnb4bit(self, hidden_states, top_k_index, top_k_weights)
        if result is not None:
            return result

    _moe_uses_fp8_expert_weights = forward_moe_backend_fp8 = None
    try:
        from unsloth_zoo.temporary_patches.moe_utils_fp8 import (
            _moe_uses_fp8_expert_weights,
            forward_moe_backend_fp8,
        )
    except ImportError:
        pass
    if _moe_uses_fp8_expert_weights is not None and _moe_uses_fp8_expert_weights(self):
        return forward_moe_backend_fp8(self, hidden_states, top_k_index, top_k_weights)

    # BF16 / FP16 decode-sized no-grad calls: only the routed experts (moe_routed.py).
    routed_moe_forward = None
    try:
        from unsloth_zoo.temporary_patches.moe_routed import routed_moe_forward
    except ImportError:
        pass
    if routed_moe_forward is not None:
        result = routed_moe_forward(self, hidden_states, top_k_index, top_k_weights)
        if result is not None:
            return result

    backend = select_moe_backend()
    if backend == "sonic_moe":
        # Absolute import: this function is copied into unsloth_compiled_cache.
        forward_sonic_moe = None
        try:
            from unsloth_zoo.temporary_patches.moe_utils_sonic import forward_sonic_moe
        except ImportError:
            pass
        if forward_sonic_moe is not None:
            return forward_sonic_moe(self, hidden_states, top_k_index, top_k_weights)
        backend = "grouped_mm"
    if backend == "grouped_mm":
        return forward_native_grouped_mm(self, hidden_states, top_k_index, top_k_weights)
    # Triton kernels assume split gate_up, SiLU, no bias: interleaved GPT-OSS gate_up takes the eager loop.
    if backend == "unsloth_triton" and not _gate_up_is_interleaved(self):
        return forward_triton_grouped_gemm(self, hidden_states, top_k_index, top_k_weights)
    return forward_native_moe_loop(self, hidden_states, top_k_index, top_k_weights)


# Test-only call counter, off by default: incrementing a module global is a Dynamo side effect, and always-on it re-traced the compiled MoE block every step.
_EXPERT_COUNT_CALLS = [0]
_COUNT_DEBUG = os.environ.get("UNSLOTH_MOE_COUNT_DEBUG", "0") == "1"


def _count_tokens_per_expert(
    flat_experts: torch.Tensor,
    num_experts: int,
    dtype: torch.dtype = torch.int32,
) -> torch.Tensor:
    """Per-expert token counts, WITHOUT synchronising the device.

    Drop-in replacement for ``torch.bincount(flat_experts, minlength=num_experts)``
    returning shape ``[num_experts]`` and the requested ``dtype``.

    Why not bincount: on CUDA the output size of ``bincount`` depends on the data
    (it must learn ``max(input)`` even when ``minlength`` is given), so the kernel
    D2H-copies and blocks the host. Measured on B200, E=256 / 16384 routed rows:
    2 sync warnings under ``torch.cuda.set_sync_debug_mode("warn")`` and ~58 us of
    host time per call, versus 0 warnings and ~19 us here. With one MoE layer per
    block that drain happens tens of times per step.

    ``scatter_add_`` accumulates with atomics, so the ORDER of accumulation is
    nondeterministic; integer addition is associative and commutative and every
    addend is exactly 1, so the SUM is bit-exact and run-to-run deterministic
    regardless of order. Verified bit-identical to ``bincount`` over random,
    skewed, empty and single-token routings, and it does not trip
    ``torch.use_deterministic_algorithms(True)``.

    Caveat, same precondition as the caller already relies on: ``flat_experts``
    must hold values in ``[0, num_experts)``. That holds for router ``topk``
    output by construction. Out-of-range values make ``bincount`` silently return
    a LONGER tensor (breaking the downstream ``offs=`` shape) whereas this writes
    out of bounds, so neither is safe; the difference is only in how it fails.
    """
    # This Unsloth Zoo code section is licensed under AGPL3
    if flat_experts.dim() != 1:
        flat_experts = flat_experts.reshape(-1)
    # scatter_add_ needs int64; router topk already gives one, so no copy.
    index = flat_experts if flat_experts.dtype == torch.int64 else flat_experts.long()
    counts = torch.zeros(num_experts, dtype=dtype, device=flat_experts.device)
    counts.scatter_add_(0, index, torch.ones_like(index, dtype=dtype))
    return counts


if _COUNT_DEBUG:
    def count_tokens_per_expert(flat_experts, num_experts, dtype=torch.int32):
        _EXPERT_COUNT_CALLS[0] += 1
        return _count_tokens_per_expert(flat_experts, num_experts, dtype)

    count_tokens_per_expert.__doc__ = _count_tokens_per_expert.__doc__
else:
    count_tokens_per_expert = _count_tokens_per_expert


def moe_routing_sort(top_k_index, num_experts):
    """(counts int32 [E], stable argsort int64 [N], cumsum(counts) int32 [E]), sync-free; Triton on CUDA."""
    # This Unsloth Zoo code section is licensed under AGPL3
    if _TRITON_ROUTING is not None:
        return _TRITON_ROUTING(top_k_index, num_experts)
    flat_experts = top_k_index.reshape(-1)
    counts = count_tokens_per_expert(flat_experts, num_experts, torch.int32)
    sorted_indices = flat_experts.argsort(stable=True)
    return counts, sorted_indices, torch.cumsum(counts, dim=0, dtype=torch.int32)


