        verdict = _wrapper_forward_applies_stash(wrapper)
        if verdict is None:
            # A compiled-only run never reaches the eager probe.
            verdict = _wrapper_forward_applies_stash(wrapper, _MOE_LORA_COMPILED_VERDICT_ATTR)
        if verdict is False:
