def weighted_unpermute(*args, **kwargs):
    """Fused Triton combine, or None so the caller falls back to the eager reduction."""
    if _resolve_weighted_unpermute() is False:
        return None
    return _WEIGHTED_UNPERMUTE(*args, **kwargs)


