@lru_cache(maxsize=1)
def _moe_gategrad_enabled() -> bool:
    """Gate-gradient identity path is on by default; UNSLOTH_MOE_GATEGRAD is read once and cached, so code toggling it
    at runtime must call _moe_gategrad_enabled.cache_clear()."""
    return os.environ.get("UNSLOTH_MOE_GATEGRAD", "1") != "0"


class _MoEGateGradIdentity(torch.autograd.Function):
    """Identity over the pre-down activation; backward gives the gate grad as <inter, dA>/gate instead of <dOut, Y>;
    exact for any linear down projection and any routing weight, zeros included (caller sign-floors the gate);
    invalid with a post-matmul down bias, so callers must disable it then."""

    @staticmethod
    def forward(ctx, inter, permuted_weights):
        ctx.save_for_backward(inter, permuted_weights)
        return inter

    @staticmethod
    @torch.autograd.function.once_differentiable
    def backward(ctx, grad_inter):
        # once_differentiable: the reconstruction is first-order exact but its
        # graph is not the original one, so create_graph must raise, not
        # silently return wrong second derivatives.
        # grad_inter is None when nothing downstream needs inter's gradient
        # (e.g. a frozen down projection); there is nothing to propagate then.
        if grad_inter is None:
            return None, None
        inter, gate = ctx.saved_tensors
        grad_gate = None
        # Skip the gate gradient when the routing weight is frozen (e.g. a frozen
        # router under LoRA), where its gradient is never consumed.
        if ctx.needs_input_grad[1]:
            dgate = (inter.to(torch.float32) * grad_inter.to(torch.float32)).sum(dim=-1)
            # The call site multiplies Y by this same sign-floored gate, so the
            # floor cancels exactly and the quotient equals <Y, dOut> for any
            # gate, including exact zeros. The re-clamp is a no-op for the safe
            # gate passed by forward_native_grouped_mm; it only protects direct
            # callers from dividing by a raw zero.
            gate_f = gate.to(torch.float32)
            safe_gate = torch.where(
                gate_f >= 0, gate_f.clamp_min(1e-12), gate_f.clamp_max(-1e-12)
            )
            grad_gate = (dgate / safe_gate).to(gate.dtype)
        # inter passes through unchanged, so its gradient is grad_inter.
        return grad_inter, grad_gate


_FLAG_MISSING = object()


def _module_flag(module, name, default = None):
    value = module.__dict__.get(name, _FLAG_MISSING)
    if value is _FLAG_MISSING:
        value = getattr(type(module), name, default)
    return value


def _gate_up_is_interleaved(module) -> bool:
    if "GptOssExperts" in module.__class__.__name__:
        return True
    return _module_flag(module, "is_concatenated", True) is False


def _uses_own_apply_gate(module) -> bool:
    """Own-gate flag on the class or (FP8) instance; hot path, so no nn.Module.__getattr__."""
    return bool(
        module.__dict__.get("_unsloth_own_apply_gate", False)
        or getattr(type(module), "_unsloth_own_apply_gate", False)
    )


def _moe_fp32_reference(module) -> bool:
    """Experts declaring `_unsloth_moe_fp32_reference` (Unsloth's native DeepSeek-V4.1) compute the gate in fp32 and
    accumulate the routed outputs in fp32, as their own forward (the reference) does."""
    return bool(_module_flag(module, "_unsloth_moe_fp32_reference", False))


def _apply_own_gate(module, gate_up):
    """module._apply_gate, in fp32 for fp32-reference experts (one rounding back to the activation dtype)."""
    if _moe_fp32_reference(module):
        return module._apply_gate(gate_up.float()).to(gate_up.dtype)
    return module._apply_gate(gate_up)


def _loop_expert_weight(param, expert_idx, dtype):
    """One expert's weight for the per-expert loop: a packed MXFP4 stack decodes only that expert."""
    if is_mxfp4_expert_param(param):
        from unsloth_zoo.mxfp4_dequant import mxfp4_dequantize

        return mxfp4_dequantize(
            param.data[expert_idx : expert_idx + 1],
            param.mxfp4_scales[expert_idx : expert_idx + 1].to(param.device),
            dtype = dtype,
            transpose = param.mxfp4_transposed,
        )[0]
    weight = param[expert_idx]
    # Cast dense 16/32-bit stacks to the activation dtype like native _expert_weight (F.linear rejects the mix); fp8/int stay.
    if weight.is_floating_point() and weight.element_size() > 1 and weight.dtype != dtype:
        weight = weight.to(dtype)
    return weight


def forward_native_grouped_mm(
    self,
    hidden_states: torch.Tensor,
    top_k_index: torch.Tensor,
    top_k_weights: torch.Tensor,
) -> torch.Tensor:
    """Native PyTorch grouped-GEMM MoE forward via torch._grouped_mm (no Triton; needs runtime support)."""
    # This Unsloth Zoo code section is licensed under AGPL3

    # Runtime safety check (defense in depth); packed NVFP4 / MXFP8 stacks fall back to a per-group loop instead.
    if not _check_torch_grouped_mm_supported() and not _GROUPED_MM_TRITON_STANDIN \
            and not _GROUPED_MM_RUNTIME_LATCHED[0] and not _moe_uses_new_packed_expert_weights(self):
        # Compute Capability is CUDA-only; on XPU it would mask this message.
        if torch.cuda.is_available():
            major, minor = torch.cuda.get_device_capability(torch.cuda.current_device())
            where = f"this device (Compute Capability {major}.{minor})"
        else:
            where = "this device"
        raise RuntimeError(
            f"torch._grouped_mm is not supported on {where}. "
            f"Set UNSLOTH_MOE_BACKEND='unsloth_triton' or 'native_torch' to use a compatible backend."
        )

    is_2d_input = hidden_states.dim() == 2
    if is_2d_input:
        sequence_length, hidden_dim = hidden_states.shape
        batch_size = 1
    else:
        batch_size, sequence_length, hidden_dim = hidden_states.shape

    hidden_states = hidden_states.view(-1, hidden_dim)
    # torch._grouped_mm is not autocast-cast, and float32 operands hit its slow per-group fallback.
    if hidden_states.dtype == torch.float32:
        _stack = self._parameters.get("gate_up_proj", self._parameters.get("gate_proj"))
        if _stack is not None and _stack.dtype in (torch.float16, torch.bfloat16):
            hidden_states = hidden_states.to(_stack.dtype)
        elif _stack is not None and _stack.dtype != torch.float32:
            hidden_states = hidden_states.to(moe_compute_dtype(hidden_states))

    # Routing: count tokens per expert, sort to group by expert, gather inputs.
    flat_top_k = top_k_index.view(-1)
    num_tokens_per_expert, sorted_indices, offsets = moe_routing_sort(top_k_index, self.num_experts)
    permuted_input = gather_routed_rows(hidden_states, sorted_indices, top_k_index.shape[-1])

    # Inside an Unsloth checkpoint: keep (first pass) or reuse (replay) the frozen base outputs.
    checkpoint_call = _gc_moe_checkpoint_call()
    keep_slot = _gc_keep_base_slot(self, checkpoint_call)

    # Gate + Up projection with optional separated LoRA (default).
    use_separated_lora = _should_use_separated_lora()
    gate_up_lora = None

    # Prefer LoRA injected by the patched ParamWrapper; fall back to the parameter.
    _stashed_gate_up_lora = take_moe_lora_stash(self, "gate_up_proj")
    if _stashed_gate_up_lora is not None:
        gate_up_lora = _stashed_gate_up_lora[:3]  # (first, second, scaling)
    elif (
        use_separated_lora
        and hasattr(self, "gate_up_proj")
        and _has_lora_adapters(self.gate_up_proj)
    ):
        gate_up_lora = _extract_lora_weights(
            self.gate_up_proj, num_experts=self.num_experts, experts_module=self
        )

    own_gate_up = None
    fused_inter = None
    selective_plan = None
    if hasattr(self, "gate_up_proj"):
        model_type = getattr(self, "_unsloth_model_type", None)
        _gate_up_src = self.gate_up_proj

        # Provider re-derives the base weight on demand so Fix 3 can recompute it in backward instead of pinning it; grouped_mm needs contiguous weights.
        def _gate_up_provider(experts=None, _src=_gate_up_src, _mt=model_type, _h=hidden_dim, _dt=hidden_states.dtype, _mod=self, _n=num_tokens_per_expert):
            return preprocess_weight(_get_base_weight(_src, _dt, _n, experts), "gate_up", _h, _mt, experts_module=_mod)
        _gate_up_layout = _mxfp4_expert_layout(_gate_up_src, "gate_up", hidden_dim, model_type, self)
        if _is_fp8_block_layout(_gate_up_layout):
            mm1_out, gate_up_lora = _fp8_block_base_mm(
                permuted_input, offsets, num_tokens_per_expert, _gate_up_layout, gate_up_lora, keep_slot, "gate_up",
            )
        elif _gate_up_layout is not None:
            mm1_out = _mxfp4_base_grouped_mm(
                permuted_input, offsets, num_tokens_per_expert, _gate_up_provider,
                _moe_recompute_enabled(_gate_up_src, dtype=hidden_states.dtype), _gate_up_layout,
            )
        else:
            mm1_out = _nf4_fused_base_mm(permuted_input, offsets, _gate_up_src, "gate_up", hidden_dim, model_type, self)
        if _gate_up_layout is None and mm1_out is None:
            _recompute = _moe_recompute_enabled(_gate_up_src, dtype=hidden_states.dtype)
            if _recompute:
                selective_plan = _selective_dequant_plan(
                    (_gate_up_src, getattr(self, "down_proj", None)), num_tokens_per_expert, permuted_input.shape[0],
                    experts_module = self, checkpoint_call = checkpoint_call,
                )
            # LoRA folded into the base GEMM (moe_lora_fold) and the first pass's base output reused by the checkpoint
            # replay (moe_gc_keep_base); a LoRA left over is added by the separated path below.
            mm1_out, gate_up_lora = _moe_base_and_lora(
                permuted_input, offsets, _gate_up_provider, _recompute, selective_plan, gate_up_lora, _gate_up_src,
                keep_slot, "gate_up",
            )

        # Separated LoRA: + ((X @ first) @ second) * scaling.
        if gate_up_lora is not None:
            first_weight, second_weight, scaling = gate_up_lora

            # Cast to input dtype (LoRA is float32) and make contiguous for grouped_mm.
            first_weight = first_weight.to(permuted_input.dtype).contiguous()
            second_weight = second_weight.to(permuted_input.dtype).contiguous()
            first_weight, second_weight = _pad_lora_rank_for_grouped_mm(first_weight, second_weight, permuted_input)

            try:
                lora_out = _grouped_mm_with_backward_fix(permuted_input, first_weight, offsets)
                lora_out = lora_out.contiguous()
            except RuntimeError as e:
                raise e

            # Second matmul; pad an unaligned output dim or fall back on failure.
            try:
                if second_weight.shape[-1] % 8 != 0:
                    pad_size = 8 - (second_weight.shape[-1] % 8)
                    second_weight_padded = F.pad(
                        second_weight, (0, pad_size)
                    ).contiguous()
                    lora_delta = _grouped_mm_with_backward_fix(
                        lora_out, second_weight_padded, offsets
                    )
                    lora_delta = lora_delta[:, :-pad_size]
                else:
                    lora_delta = _grouped_mm_with_backward_fix(
                        lora_out, second_weight, offsets
                    )
            except RuntimeError:
                # Manual loop fallback on grouped_mm failure (e.g. stride alignment).
                lora_delta = torch.empty(
                    (lora_out.shape[0], second_weight.shape[-1]),
                    dtype=lora_out.dtype,
                    device=lora_out.device,
                )
                cpu_offsets = offsets.cpu().tolist()
                prev_offset = 0
                for i, end in enumerate(cpu_offsets):
                    if prev_offset < end:
                        lora_delta[prev_offset:end] = torch.matmul(
                            lora_out[prev_offset:end], second_weight[i]
                        )
                    prev_offset = end

            mm1_out = mm1_out + lora_delta * scaling

        if hasattr(self, "gate_up_proj_bias") and self.gate_up_proj_bias is not None:
            # repeat_interleave without output_size= forces a D2H sync; sorted_indices is already in expert order, so
            # gathering by expert id matches it and is sync-free.
            sorted_expert_ids = flat_top_k[sorted_indices]
            bias_expanded = _gather_expert_bias(self.gate_up_proj_bias, sorted_expert_ids)
            mm1_out = mm1_out + bias_expanded.to(mm1_out.dtype)

        _interleaved = _gate_up_is_interleaved(self)
        if _interleaved:
            gate = mm1_out[..., ::2]
            up = mm1_out[..., 1::2]
        else:
            gate, up = mm1_out.chunk(2, dim=-1)
        own_gate_up = mm1_out if _uses_own_apply_gate(self) else None
        if own_gate_up is None:
            fused_inter = _fused_moe_activation(self, mm1_out, _interleaved)

    elif hasattr(self, "w1") and hasattr(self, "w3"):
        # Separate w1/w3 weights (older models).
        w1_base = _get_base_weight(self.w1)
        w3_base = _get_base_weight(self.w3)

        w1 = w1_base.transpose(-2, -1)
        w3 = w3_base.transpose(-2, -1)

        gate = _grouped_mm_with_backward_fix(permuted_input, w1, offsets)
        up = _grouped_mm_with_backward_fix(permuted_input, w3, offsets)

        # Add LoRA for w1 and w3 separately if present.
        if use_separated_lora:
            if _has_lora_adapters(self.w1):
                w1_lora = _extract_lora_weights(self.w1, experts_module=self)
                if w1_lora is not None:
                    lora_A, lora_B, scaling = w1_lora
                    lora_A_t, lora_B_t = _pad_lora_rank_for_grouped_mm(
                        lora_A.transpose(-2, -1), lora_B.transpose(-2, -1), permuted_input
                    )
                    lora_A_out = _grouped_mm_with_backward_fix(
                        permuted_input, lora_A_t, offsets
                    )
                    lora_B_out = _grouped_mm_with_backward_fix(lora_A_out, lora_B_t, offsets)
                    gate = gate + lora_B_out * scaling

            if _has_lora_adapters(self.w3):
                w3_lora = _extract_lora_weights(self.w3, experts_module=self)
                if w3_lora is not None:
                    lora_A, lora_B, scaling = w3_lora
                    lora_A_t, lora_B_t = _pad_lora_rank_for_grouped_mm(
                        lora_A.transpose(-2, -1), lora_B.transpose(-2, -1), permuted_input
                    )
                    lora_A_out = _grouped_mm_with_backward_fix(
                        permuted_input, lora_A_t, offsets
                    )
                    lora_B_out = _grouped_mm_with_backward_fix(lora_A_out, lora_B_t, offsets)
                    up = up + lora_B_out * scaling
    else:
        raise AttributeError("MoE layer must have 'gate_up_proj' or 'w1'/'w3'.")

    # Activation
    if own_gate_up is not None:
        inter = _apply_own_gate(self, own_gate_up)
    elif fused_inter is not None:
        inter = fused_inter
    elif "GptOssExperts" in self.__class__.__name__:
        # Custom GptOss activation.
        limit = getattr(self, "limit", 7.0)
        alpha = getattr(self, "alpha", 1.702)

        gate = gate.clamp(min=None, max=limit)
        up = up.clamp(min=-limit, max=limit)
        glu = gate * torch.sigmoid(gate * alpha)
        inter = (up + 1.0) * glu
    elif hasattr(self, 'act_fn') and callable(self.act_fn):
        inter = self.act_fn(gate) * up
    else:
        inter = F.silu(gate) * up

    # Env-gated gate-grad identity; off with a down bias (identity assumes linear down), a frozen router, or fp16 (kept
    # on the standard multiply, since grad_inter = gate * (W2 @ dOut) underflows to 0 for near-zero gates); bf16/fp32
    # unaffected.
    _gategrad = (
        _moe_gategrad_enabled()
        and getattr(self, "down_proj_bias", None) is None
        and top_k_weights.requires_grad
        and inter.dtype != torch.float16
    )
    permuted_weights = None
    if _gategrad:
        raw_weights = top_k_weights.reshape(-1)[sorted_indices]
        # Sign-floor the gate away from zero (straight-through to top_k_weights), with the same value in multiply and
        # identity divide so <Y, dOut> survives a zero weight; fp16 cannot represent eps=1e-12, so upcast to float32;
        # forward changes by at most 1e-12 * |Y| when |gate| < 1e-12.
        if raw_weights.dtype == torch.float16:
            raw_weights = raw_weights.to(torch.float32)
        eps = 1e-12
        floored = torch.where(
            raw_weights >= 0,
            raw_weights.clamp(min=eps),
            raw_weights.clamp(max=-eps),
        )
        permuted_weights = raw_weights + (floored - raw_weights).detach()
        inter = _MoEGateGradIdentity.apply(inter, permuted_weights)

    # Down projection with optional separated LoRA (default).
    down_lora = None

    # Prefer LoRA injected by the patched ParamWrapper; fall back to the parameter.
    _stashed_down_lora = take_moe_lora_stash(self, "down_proj")
    if _stashed_down_lora is not None:
        down_lora = _stashed_down_lora[:3]  # (first, second, scaling)
    elif (
        use_separated_lora
        and hasattr(self, "down_proj")
        and _has_lora_adapters(self.down_proj)
    ):
        down_lora = _extract_lora_weights(self.down_proj, num_experts=self.num_experts, experts_module=self)

    if hasattr(self, "down_proj"):
        model_type = getattr(self, "_unsloth_model_type", None)
        _down_src = self.down_proj
        def _down_provider(experts=None, _src=_down_src, _mt=model_type, _h=hidden_dim, _dt=hidden_states.dtype, _mod=self, _n=num_tokens_per_expert):
            return preprocess_weight(_get_base_weight(_src, _dt, _n, experts), "down", _h, _mt, experts_module=_mod)
        _down_layout = _mxfp4_expert_layout(_down_src, "down", hidden_dim, model_type, self)
        if _is_fp8_block_layout(_down_layout):
            mm2_out, down_lora = _fp8_block_base_mm(
                inter, offsets, num_tokens_per_expert, _down_layout, down_lora, keep_slot, "down",
            )
        elif _down_layout is not None:
            mm2_out = _mxfp4_base_grouped_mm(
                inter, offsets, num_tokens_per_expert, _down_provider,
                _moe_recompute_enabled(_down_src, dtype=hidden_states.dtype), _down_layout,
            )
        else:
            mm2_out = _nf4_fused_base_mm(inter, offsets, _down_src, "down", hidden_dim, model_type, self)
        if _down_layout is None and mm2_out is None:
            _recompute = _moe_recompute_enabled(_down_src, dtype=hidden_states.dtype)
            mm2_out, down_lora = _moe_base_and_lora(
                inter, offsets, _down_provider, _recompute, selective_plan if _recompute else None, down_lora,
                _down_src, keep_slot, "down",
            )

        if down_lora is not None:
            first_weight, second_weight, scaling = down_lora

            # Cast to input dtype (LoRA is float32) and make contiguous for grouped_mm.
            first_weight = first_weight.to(inter.dtype).contiguous()
            second_weight = second_weight.to(inter.dtype).contiguous()
            first_weight, second_weight = _pad_lora_rank_for_grouped_mm(first_weight, second_weight, inter)

            lora_out = _grouped_mm_with_backward_fix(inter, first_weight, offsets)
            lora_out = lora_out.contiguous()

            try:
                lora_delta = _grouped_mm_with_backward_fix(lora_out, second_weight, offsets)
            except RuntimeError:
                # Manual loop fallback.
                lora_delta = torch.empty(
                    (lora_out.shape[0], second_weight.shape[-1]),
                    dtype=lora_out.dtype,
                    device=lora_out.device,
                )
                cpu_offsets = offsets.cpu().tolist()
                prev_offset = 0
                for i, end in enumerate(cpu_offsets):
                    if prev_offset < end:
                        lora_delta[prev_offset:end] = torch.matmul(
                            lora_out[prev_offset:end], second_weight[i]
                        )
                    prev_offset = end

            mm2_out = mm2_out + lora_delta * scaling

        if hasattr(self, "down_proj_bias") and self.down_proj_bias is not None:
            # Capture-safe gather; see gate_up_proj_bias above.
            sorted_expert_ids = flat_top_k[sorted_indices]
            bias_expanded = _gather_expert_bias(self.down_proj_bias, sorted_expert_ids).to(mm2_out.device)
            mm2_out = mm2_out + bias_expanded.to(mm2_out.dtype)

    elif hasattr(self, "w2"):
        w2_base = _get_base_weight(self.w2)
        w2 = w2_base.transpose(-2, -1)
        mm2_out = _grouped_mm_with_backward_fix(inter, w2, offsets)

        if use_separated_lora and _has_lora_adapters(self.w2):
            w2_lora = _extract_lora_weights(self.w2, experts_module=self)
            if w2_lora is not None:
                lora_A, lora_B, scaling = w2_lora
                lora_A_t, lora_B_t = _pad_lora_rank_for_grouped_mm(
                    lora_A.transpose(-2, -1), lora_B.transpose(-2, -1), inter
                )
                lora_A_out = _grouped_mm_with_backward_fix(inter, lora_A_t.contiguous(), offsets)
                lora_B_t = lora_B_t.contiguous()
                lora_B_out = _grouped_mm_with_backward_fix(lora_A_out, lora_B_t, offsets)
                mm2_out = mm2_out + lora_B_out * scaling
    else:
        raise AttributeError("MoE layer must have 'down_proj' or 'w2'.")

    # Apply routing weights and scatter-add (reduce).
    if _gategrad:
        # Gate grad comes from the identity; detach so the multiply does not pin Y.
        permuted_weights = permuted_weights.detach()
    else:
        flat_weights = top_k_weights.reshape(-1)
        permuted_weights = flat_weights[sorted_indices]
    if _moe_fp32_reference(self):
        permuted_weights = permuted_weights.float()

    final_hidden_states = weighted_unpermute(
        mm2_out,
        sorted_indices,
        permuted_weights,
        batch_size * sequence_length,
        top_k_index.shape[-1],
        out_dtype = hidden_states.dtype,
    )
    if final_hidden_states is None:
        mm2_out = mm2_out * permuted_weights.unsqueeze(-1)
        final_hidden_states = combine_permuted_moe_outputs(
            mm2_out,
            sorted_indices,
            batch_size * sequence_length,
            top_k_index.shape[-1],
            out_dtype = hidden_states.dtype,
        )

    if is_2d_input:
        return final_hidden_states

    return final_hidden_states.view(batch_size, sequence_length, hidden_dim)


def _experts_are_input_major(module, name, in_dim) -> bool:
    if bool(_module_flag(module, "_unsloth_grouped_mm_format", False)):
        return True
    declared = _module_flag(module, "is_transposed", None)
    if isinstance(declared, bool):
        return declared
    return getattr(module, name).shape[-1] != in_dim


TRITON_MOE_COMPUTE_DTYPE_STATS = {"cast": 0, "kept_fp32": 0}


def _triton_moe_compute_dtype(module, hidden_states):
    """bf16 for float32 activations into bf16 experts (matches autocast); float16 is left alone (overflow)."""
    if hidden_states.dtype != torch.float32:
        return hidden_states.dtype
    for name in ("gate_up_proj", "down_proj"):
        weight = getattr(module, name, None)
        if not isinstance(weight, torch.Tensor) or weight.dtype != torch.bfloat16:
            return hidden_states.dtype
    if os.environ.get("UNSLOTH_FORCE_FLOAT32", "0") == "1":
        return hidden_states.dtype
    keep = os.environ.get("UNSLOTH_MOE_TRITON_FP32", "0") == "1"
    # Eager only: Dynamo would recompile on every counter value.
    if not torch.compiler.is_compiling():
        TRITON_MOE_COMPUTE_DTYPE_STATS["kept_fp32" if keep else "cast"] += 1
    return hidden_states.dtype if keep else torch.bfloat16


@torch.compiler.disable
def _moe_weight_dtype_kwargs(tuner, module, name, dtype, device = None):
    """Supplies the weight_dtype kwarg when expert weights differ from activations (bf16 W, float32 X); the operands'
    CUDA device is used since mixed-GPU hosts need configs for that card."""
    try:
        parameters = inspect.signature(tuner).parameters
    except (TypeError, ValueError):
        return {}
    kwargs = {}
    weight = getattr(module, name, None)
    weight_dtype = getattr(weight, "dtype", None)
    if weight_dtype in (torch.float32, torch.bfloat16, torch.float16) and weight_dtype != dtype \
            and "weight_dtype" in parameters:
        kwargs["weight_dtype"] = weight_dtype
    # Older unsloth has no device argument and reads the current device.
    if device is not None and device.type == "cuda" and "device" in parameters:
        kwargs["device"] = device
    return kwargs


# tl.dot needs tile dims >= 16 and kernels static_assert K % BLOCK_SIZE_K == 0 (N likewise); the tile fitter stops at
# 16, so non-multiple-of-16 hidden or intermediate sizes cannot compile.
_TRITON_GROUPED_GEMM_DIM_MULTIPLE = 16


def _triton_grouped_gemm_dims_supported(module, hidden_dim) -> bool:
    try:
        gate_up = module.gate_up_proj
        if _experts_are_input_major(module, "gate_up_proj", hidden_dim):
            intermediate_dim = gate_up.shape[-1] // 2
        else:
            intermediate_dim = gate_up.shape[1] // 2
    except Exception:
        return True
    m = _TRITON_GROUPED_GEMM_DIM_MULTIPLE
    return hidden_dim % m == 0 and intermediate_dim % m == 0


def _triton_moe_tensors_on_gpu(module, hidden_states) -> bool:
    """The Triton grouped-GEMM kernels need CUDA / HIP tensors. The unsloth_triton backend is chosen once per process,
    but a call's tensors can still live off the GPU (a CPU reference model, a CPU-offloaded expert stack)."""
    if hidden_states.device.type != "cuda":
        return False
    for name in ("gate_up_proj", "down_proj"):
        weight = getattr(module, name, None)
        if isinstance(weight, torch.Tensor) and weight.device.type != "cuda":
            return False
    return True


def forward_triton_grouped_gemm(
    self,
    hidden_states: torch.Tensor,
    top_k_index: torch.Tensor,
    top_k_weights: torch.Tensor,
) -> torch.Tensor:
    """Grouped-GEMM MoE forward via Triton kernels (torch.compile-compatible, mode="max-autotune")."""
    # This Unsloth Zoo code section is licensed under AGPL3

    # Tensors off the GPU run the eager loop. moe_utils.py is installed into the compiled cache as a whole file, so the
    # helper travels with this function, as _triton_grouped_gemm_dims_supported below does.
    if not _triton_moe_tensors_on_gpu(self, hidden_states):
        return forward_native_moe_loop(self, hidden_states, top_k_index, top_k_weights)

    packed = any(is_mxfp4_expert_param(getattr(self, name, None)) for name in ("gate_up_proj", "down_proj"))
    if packed or not _triton_grouped_gemm_dims_supported(self, hidden_states.shape[-1]):
        # Toy shapes (hidden_size 8): the same routing on grouped_mm, else the eager loop; neither has the tile limit.
        # Packed MXFP4 expert stacks: the raw Triton GEMM reads dense weights; grouped_mm and the loop decode them.
        if _grouped_mm_supported_on(hidden_states.device):
            return forward_native_grouped_mm(self, hidden_states, top_k_index, top_k_weights)
        return forward_native_moe_loop(self, hidden_states, top_k_index, top_k_weights)

    from unsloth.kernels.moe.grouped_gemm.interface import grouped_gemm
    from unsloth.kernels.moe.autotune_cache import get_or_autotune_moe_kernels

    if not hasattr(self, "_unsloth_moe_configs"):
        self._unsloth_moe_configs = None

    use_separated_lora = _should_use_separated_lora()

    # gate_up LoRA from the patched ParamWrapper (mirrors the down block below).
    gate_up_lora = None
    _stashed_gate_up_lora = take_moe_lora_stash(self, "gate_up_proj")
    if _stashed_gate_up_lora is not None:
        gate_up_lora = _stashed_gate_up_lora[:3]
    elif (
        use_separated_lora
        and hasattr(self, "gate_up_proj")
        and _has_lora_adapters(self.gate_up_proj)
    ):
        gate_up_lora = _extract_lora_weights(
            self.gate_up_proj, num_experts=self.num_experts
        )

    # Flatten 3D inputs (batch_size, seq_len, hidden_dim).
    is_3d = hidden_states.dim() == 3
    if is_3d:
        batch_size, seq_len, hidden_dim = hidden_states.shape
        hidden_states = hidden_states.view(-1, hidden_dim)
        num_tokens = batch_size * seq_len
        if top_k_index.dim() == 3:
            top_k_index = top_k_index.view(-1, top_k_index.shape[-1])
        if top_k_weights.dim() == 3:
            top_k_weights = top_k_weights.view(-1, top_k_weights.shape[-1])
    else:
        num_tokens, hidden_dim = hidden_states.shape

    top_k = top_k_index.shape[1]
    compute_dtype = _triton_moe_compute_dtype(self, hidden_states)
    # The gate_up GEMM reads X in compute_dtype as plain bf16 training does; a float32 X runs in float32, whose default
    # tile does not fit L4 shared memory; fp16 and the FP32 flags keep float32; LoRA and routing sum keep the caller's
    # dtype.
    gemm_hidden_states = hidden_states if hidden_states.dtype == compute_dtype else hidden_states.to(compute_dtype)

    # Configs fit the operand dtypes and the card's shared memory: re-select eagerly after module.to(); a traced call
    # keeps the last configs (the tuner is compiler-disabled). Caller-preset configs without a key are kept.
    configs_key = (
        compute_dtype,
        getattr(self.gate_up_proj, "dtype", None),
        getattr(self.down_proj, "dtype", None),
        hidden_states.device,
    )
    if getattr(self, "_unsloth_moe_configs_key", configs_key) != configs_key and not torch.compiler.is_compiling():
        self._unsloth_moe_configs = None

    if self._unsloth_moe_configs is None:
        if _experts_are_input_major(self, "gate_up_proj", hidden_dim):
            intermediate_dim = self.gate_up_proj.shape[-1] // 2
        else:
            intermediate_dim = self.gate_up_proj.shape[1] // 2

        # The autotuner doubles intermediate_dim itself: a doubled N can tune a BLOCK_SIZE_N the real N does not divide.
        gemm1_configs = get_or_autotune_moe_kernels(
            num_experts=self.num_experts,
            hidden_dim=hidden_dim,
            intermediate_dim=intermediate_dim,
            top_k=top_k,
            dtype=gemm_hidden_states.dtype,
            **_moe_weight_dtype_kwargs(
                get_or_autotune_moe_kernels, self, "gate_up_proj", gemm_hidden_states.dtype, gemm_hidden_states.device,
            ),
        )

        # Second GEMM: K = intermediate_dim, N = hidden_dim.
        gemm2_configs = get_or_autotune_moe_kernels(
            num_experts=self.num_experts,
            hidden_dim=intermediate_dim,
            intermediate_dim=hidden_dim // 2 if hidden_dim % 2 == 0 else hidden_dim,
            top_k=top_k,
            dtype=compute_dtype,
            **_moe_weight_dtype_kwargs(
                get_or_autotune_moe_kernels, self, "down_proj", compute_dtype, gemm_hidden_states.device,
            ),
        )

        self._unsloth_moe_configs = (intermediate_dim, gemm1_configs, gemm2_configs)
        self._unsloth_moe_configs_key = configs_key
        torch.cuda.empty_cache()

    intermediate_dim, gemm1_configs, gemm2_configs = self._unsloth_moe_configs
    fwd_config_1, bwd_dX_config_1, bwd_dW_config_1 = gemm1_configs
    fwd_config_2, bwd_dX_config_2, bwd_dW_config_2 = gemm2_configs

    with torch.no_grad():
        token_counts_by_expert, gather_indices, offsets = moe_routing_sort(top_k_index, self.num_experts)

    if _experts_are_input_major(self, "gate_up_proj", hidden_dim):
        w1 = self.gate_up_proj.transpose(-2, -1).contiguous()
    else:
        w1 = self.gate_up_proj

    # First grouped GEMM: gate_up projection.
    first_gemm_output = grouped_gemm(
        X=gemm_hidden_states,
        W=w1,
        m_sizes=token_counts_by_expert,
        topk=top_k,
        gather_indices=gather_indices,
        permute_x=True,
        permute_y=False,
        autotune=False,  # cached configs
        kernel_config_fwd=fwd_config_1,
        kernel_config_bwd_dX=bwd_dX_config_1,
        kernel_config_bwd_dW=bwd_dW_config_1,
        is_first_gemm=True,
    )

    # Separated gate_up LoRA: grouped_gemm ran with permute_x=True so first_gemm_output is expert-sorted;
    # _apply_lora_grouped_mm wants pre-permuted input, gathered via gather_indices // top_k (sorted row to token row).
    if gate_up_lora is not None:
        first_weight, second_weight, scaling = gate_up_lora
        first_weight = first_weight.to(hidden_states.dtype)
        second_weight = second_weight.to(hidden_states.dtype)
        permuted_hidden = gather_routed_rows(hidden_states, gather_indices, top_k)
        gate_up_lora_delta = _apply_lora_grouped_mm(
            permuted_hidden,
            first_weight,
            second_weight,
            offsets,
            scaling,
            grouped_mm_func=native_moe_grouped_mm,
        )
        first_gemm_output = first_gemm_output + gate_up_lora_delta

    if first_gemm_output.dtype != compute_dtype:
        first_gemm_output = first_gemm_output.to(compute_dtype)

    # Activation + gate*up.
    fused_intermediate = None
    if not _uses_own_apply_gate(self):
        fused_intermediate = _fused_moe_activation(self, first_gemm_output, False, allow_gptoss = False)
    if _uses_own_apply_gate(self):
        intermediate = _apply_own_gate(self, first_gemm_output)
    elif fused_intermediate is not None:
        intermediate = fused_intermediate
    elif hasattr(self, 'act_fn') and callable(self.act_fn):
        gate, up = first_gemm_output.chunk(2, dim=-1)
        intermediate = self.act_fn(gate) * up
    else:
        intermediate = _silu_and_mul(first_gemm_output)

    # Grouped GEMM 2: down projection.
    down_lora = None
    _stashed_down_lora = take_moe_lora_stash(self, "down_proj")
    if _stashed_down_lora is not None:
        down_lora = _stashed_down_lora[:3]
    elif (
        use_separated_lora
        and hasattr(self, "down_proj")
        and _has_lora_adapters(self.down_proj)
    ):
        down_lora = _extract_lora_weights(self.down_proj, num_experts=self.num_experts)

    if _experts_are_input_major(self, "down_proj", intermediate.shape[-1]):
        w2 = self.down_proj.transpose(-2, -1).contiguous()
    else:
        w2 = self.down_proj

    second_gemm_output = grouped_gemm(
        X=intermediate,
        W=w2,
        m_sizes=token_counts_by_expert,
        topk=top_k,
        gather_indices=gather_indices,
        permute_x=False,
        permute_y=True,
        autotune=False,  # cached configs
        kernel_config_fwd=fwd_config_2,
        kernel_config_bwd_dX=bwd_dX_config_2,
        kernel_config_bwd_dW=bwd_dW_config_2,
        is_first_gemm=False,
    )

    # Separated LoRA for down (intermediate already permuted from step 1, same offsets).
    if down_lora is not None:
        first_weight, second_weight, scaling = down_lora

        first_weight = first_weight.to(intermediate.dtype)
        second_weight = second_weight.to(intermediate.dtype)

        lora_delta = _apply_lora_grouped_mm(
            intermediate,
            first_weight,
            second_weight,
            offsets,
            scaling,
            grouped_mm_func=native_moe_grouped_mm
        )

        # permute_y=True puts second_gemm_output in token order while lora_delta is still expert-sorted, so it is
        # scattered with index_add_ rather than added row-for-row.
        if lora_delta.dtype == second_gemm_output.dtype:
            second_gemm_output.index_add_(0, gather_indices, lora_delta)
        else:
            # index_add_ requires matching dtypes; the plain add this replaced promoted.
            promoted = torch.promote_types(second_gemm_output.dtype, lora_delta.dtype)
            second_gemm_output = second_gemm_output.to(promoted).index_add(
                0, gather_indices, lora_delta.to(promoted)
            )

    # Apply routing weights and sum across top_k: (num_tokens, top_k, hidden) -> (num_tokens, hidden).
    if _moe_fp32_reference(self):
        final_hidden_states = (
            second_gemm_output.view(num_tokens, top_k, hidden_dim).float()
            * top_k_weights.float()[..., None]
        ).sum(dim=1).to(hidden_states.dtype)
    else:
        top_k_weights_casted = top_k_weights.to(hidden_states.dtype)
        final_hidden_states = (
            second_gemm_output.view(num_tokens, top_k, hidden_dim)
            * top_k_weights_casted[..., None]
        )
        final_hidden_states = final_hidden_states.sum(dim=1)

    if is_3d:
        final_hidden_states = final_hidden_states.view(batch_size, seq_len, hidden_dim)

    return final_hidden_states


@torch.compiler.disable
def forward_native_moe_loop(
    self,
    hidden_states: torch.Tensor,
    top_k_index: torch.Tensor,
    top_k_weights: torch.Tensor,
) -> torch.Tensor:
    """Loop over experts with routed tokens; torch.compile-disabled to avoid graph breaks on dynamic control flow."""
    # This Unsloth Zoo code section is licensed under AGPL3
    fp32_reference = _moe_fp32_reference(self)
    final_hidden_states = torch.zeros_like(
        hidden_states, dtype = torch.float32 if fp32_reference else hidden_states.dtype
    )
    use_separated_lora = _should_use_separated_lora()

    gate_up_lora = take_moe_lora_stash(self, "gate_up_proj")
    if gate_up_lora is not None:
        gate_up_lora = gate_up_lora[:3]
    elif (
        use_separated_lora
        and hasattr(self, "gate_up_proj")
        and _has_lora_adapters(self.gate_up_proj)
    ):
        gate_up_lora = _extract_lora_weights(
            self.gate_up_proj, num_experts=self.num_experts, experts_module=self
        )
    # Pre-cast LoRA factors to the activation dtype once (avoid per-expert .to()).
    # `scaling` is left alone: a Python float is a no-op, a tensor broadcasts.
    if gate_up_lora is not None:
        _gate_up_first, _gate_up_second, _gate_up_scaling = gate_up_lora
        gate_up_lora = (
            _gate_up_first.to(hidden_states.dtype),
            _gate_up_second.to(hidden_states.dtype),
            _gate_up_scaling,
        )

    down_lora = take_moe_lora_stash(self, "down_proj")
    if down_lora is not None:
        down_lora = down_lora[:3]
    elif (
        use_separated_lora
        and hasattr(self, "down_proj")
        and _has_lora_adapters(self.down_proj)
    ):
        down_lora = _extract_lora_weights(
            self.down_proj, num_experts=self.num_experts, experts_module=self
        )
    if down_lora is not None:
        _down_first, _down_second, _down_scaling = down_lora
        down_lora = (
            _down_first.to(hidden_states.dtype),
            _down_second.to(hidden_states.dtype),
            _down_scaling,
        )

    # Stable sort keeps torch.where(one_hot)'s (slot, token) row order: bit-identical results.
    with torch.no_grad():
        n_tokens = top_k_index.shape[0]
        slot_major = top_k_index.t().reshape(-1)   # position = top_k_pos * n_tokens + token
        expert_counts, order, _ = moe_routing_sort(slot_major, self.num_experts)
        routed_token_idx = order % n_tokens
        routed_top_k_pos = order // n_tokens
        expert_counts = expert_counts.tolist()

    # A declared (E, in, out) layout (_unsloth_grouped_mm_format) wins over the shape test, which a square stack defeats.
    grouped_mm_format = bool(_module_flag(self, "_unsloth_grouped_mm_format", False)) or (
        _module_flag(self, "is_transposed", None) is True
    )

    # Interleaved storage is a layout flag; GPT-OSS's clamped swiglu is its own activation: keep them apart.
    interleaved = _gate_up_is_interleaved(self)
    is_gpt_oss = "GptOssExperts" in self.__class__.__name__
    own_apply_gate = _uses_own_apply_gate(self)

    row_end = 0
    for expert_idx, count in enumerate(expert_counts):
        row_start, row_end = row_end, row_end + count
        if count == 0:
            continue
        token_idx = routed_token_idx[row_start:row_end]
        top_k_pos = routed_top_k_pos[row_start:row_end]
        current_state = hidden_states[token_idx]

        # gate_up projection for this expert ('gate_up_proj' or 'w1'/'w3').
        if hasattr(self, "gate_up_proj"):
            gate_up_weight = _loop_expert_weight(self.gate_up_proj, expert_idx, current_state.dtype)
            if grouped_mm_format or gate_up_weight.shape[-1] != current_state.shape[-1]:
                gate_up_weight = gate_up_weight.T
            gate_up = F.linear(current_state, gate_up_weight)
            if gate_up_lora is not None:
                first_weight, second_weight, scaling = gate_up_lora
                lora_delta = current_state @ first_weight[expert_idx]
                lora_delta = lora_delta @ second_weight[expert_idx]
                gate_up = gate_up + lora_delta * scaling
            gate_up_bias = getattr(self, "gate_up_proj_bias", None)
            if gate_up_bias is not None:
                gate_up = gate_up + gate_up_bias[expert_idx].to(gate_up.dtype)
            if interleaved:
                gate = gate_up[..., ::2]
                up = gate_up[..., 1::2]
            else:
                gate, up = gate_up.chunk(2, dim=-1)
        else:
            gate = F.linear(current_state, self.w1[expert_idx])
            up = F.linear(current_state, self.w3[expert_idx])
            gate_up = None

        if own_apply_gate:
            current_hidden_states = _apply_own_gate(
                self, gate_up if gate_up is not None else torch.cat((gate, up), dim=-1)
            )
        elif is_gpt_oss:
            limit = getattr(self, "limit", 7.0)
            alpha = getattr(self, "alpha", 1.702)
            gate = gate.clamp(min=None, max=limit)
            up = up.clamp(min=-limit, max=limit)
            current_hidden_states = (up + 1.0) * (gate * torch.sigmoid(gate * alpha))
        elif hasattr(self, "act_fn") and callable(self.act_fn):
            current_hidden_states = self.act_fn(gate) * up
        else:
            current_hidden_states = F.silu(gate) * up

        # down projection for this expert.
        if hasattr(self, "down_proj"):
            down_weight = _loop_expert_weight(self.down_proj, expert_idx, current_hidden_states.dtype)
            # Mirror gate_up: prefer the flag over the shape heuristic (unsafe at square dims).
            if grouped_mm_format or down_weight.shape[-1] != current_hidden_states.shape[-1]:
                down_weight = down_weight.T
            down = F.linear(current_hidden_states, down_weight)
            if down_lora is not None:
                first_weight, second_weight, scaling = down_lora
                lora_delta = current_hidden_states @ first_weight[expert_idx]
                lora_delta = lora_delta @ second_weight[expert_idx]
                down = down + lora_delta * scaling
            down_bias = getattr(self, "down_proj_bias", None)
            if down_bias is not None:
                down = down + down_bias[expert_idx].to(down.dtype)
            current_hidden_states = down
        else:
            current_hidden_states = F.linear(current_hidden_states, self.w2[expert_idx])

        routing_weights = top_k_weights[token_idx, top_k_pos, None]
        if fp32_reference:
            current_hidden_states = current_hidden_states.float()
            routing_weights = routing_weights.float()
        current_hidden_states = current_hidden_states * routing_weights

        final_hidden_states.index_add_(
            0, token_idx, current_hidden_states.to(final_hidden_states.dtype)
        )

    return final_hidden_states.to(hidden_states.dtype) if fp32_reference else final_hidden_states
